const C = (term, definition, en = term) => ({ term, definition, en })

const U = ({ route, slug, title, question, core, subsystem, sources, concepts, sequence, quantities, caseStudy, failures, misconception, transfer, lab }) => ({
  route, slug, title, question, core, subsystem, sourceIds: [...sources, 'source.encyclopedia.original-synthesis'],
  concepts: concepts.map(([term, definition, en]) => C(term, definition, en)), sequence, quantities,
  caseStudy, failures, misconception, transfer, lab,
  sourcePolicy: 'La fuente histórica explica teoría, progresión o un caso dentro de su fecha. Todo dato de calibre, producto, tolerancia o procedimiento operativo requiere además documentación vigente de la referencia y el estado de seguridad visible en la ficha de fuente.',
})

const THEORY_UNITS = [
  U({ route:'history-language', slug:'toh-tiempo-escalas', title:'Tiempo, escalas y calendario civil', question:'¿Cómo se pasa de un fenómeno astronómico irregular a una escala temporal utilizable?', core:'La rotación terrestre, la traslación, el día solar, el tiempo sidéreo, las zonas y el calendario responden a problemas distintos. Una escala de tiempo es una convención realizada mediante referencias y reglas; no debe confundirse con la lectura de un reloj particular.', subsystem:'timekeeping-principles', sources:['source.private.toh.ch01','source.official.bipm.vim'], concepts:[['escala temporal','Sistema de referencias y reglas para ordenar sucesos y expresar intervalos.'],['tiempo solar aparente','Lectura ligada al movimiento solar aparente, afectada por la ecuación del tiempo.'],['calendario civil','Convención que agrupa días y ajusta ciclos astronómicos a usos sociales.']], sequence:['observar un ciclo','definir una referencia','establecer unidad y origen','corregir irregularidades','distribuir la escala','mostrar fecha y hora'], quantities:['día solar y sidéreo','año trópico','desfase de zona','regla de año bisiesto'], caseStudy:'Un reloj solar y un reloj atómico pueden discrepar sin que uno esté averiado: realizan referencias diferentes y necesitan reglas de conversión. La fecha civil tampoco se obtiene contando oscilaciones sin una convención de meses y bisiestos.', failures:['Llamar tiempo a cualquier lectura horaria.','Tratar zona horaria y longitud geográfica como equivalentes exactos.'], misconception:{expression:'El mediodía solar siempre coincide con las 12:00', correction:'la zona legal, la longitud y la ecuación del tiempo separan ambas lecturas.'}, transfer:'Explica por qué dos relojes correctos pueden mostrar escalas distintas y documenta la conversión necesaria.' }),
  U({ route:'history-language', slug:'toh-instrumentos-principios', title:'Instrumentos de tiempo: flujo, oscilación y conteo', question:'¿Qué familias de instrumentos aparecen al cambiar la referencia y el modo de contar?', core:'Relojes solares, clepsidras, osciladores mecánicos y sistemas electrónicos materializan funciones comunes con fenómenos diferentes. La comparación útil separa fuente, referencia, mantenimiento, conteo, transmisión e indicación.', subsystem:'horological-history', sources:['source.private.toh.ch02','source.external.jomashop-history'], concepts:[['instrumento de flujo','Dispositivo que infiere duración a partir de una transferencia acumulada de materia.'],['reloj oscilatorio','Instrumento que cuenta ciclos de un sistema periódico mantenido.'],['realización de la referencia','Conjunto físico que hace observable una frecuencia o periodicidad elegida.']], sequence:['elegir fenómeno','mantener condiciones','observar repetición o flujo','acumular conteo','calibrar escala','presentar resultado'], quantities:['periodo','caudal','sensibilidad ambiental','resolución'], caseStudy:'Una clepsidra cambia su caudal con la altura de líquido; un péndulo cambia con longitud y gravedad; un cuarzo cambia con temperatura y envejecimiento. Los tres exigen condiciones y calibración, aunque sus piezas no se parezcan.', failures:['Ordenar instrumentos solo por fecha.','Suponer que una referencia electrónica carece de deriva.'], misconception:{expression:'Los relojes modernos eliminan la necesidad de calibración', correction:'cambia la magnitud dominante, pero toda realización posee sensibilidad, incertidumbre y envejecimiento.'}, transfer:'Construye una tabla funcional de reloj solar, clepsidra, péndulo, volante y cuarzo.' }),
  U({ route:'history-language', slug:'toh-cronometro-precision', title:'Reloj, cronómetro, precisión y exactitud', question:'¿Qué puede afirmarse cuando un reloj coincide con una referencia durante una observación?', core:'Coincidencia instantánea, marcha media, estabilidad, repetibilidad y certificación no son sinónimos. La palabra cronómetro implica un contexto de ensayo; la exactitud exige una referencia y la precisión describe dispersión bajo condiciones declaradas.', subsystem:'technical-literacy', sources:['source.private.toh.ch01','source.official.nist.uncertainty'], concepts:[['error de indicación','Diferencia entre lectura y valor de referencia en una condición.'],['marcha','Variación de la indicación acumulada por unidad de tiempo.'],['repetibilidad','Proximidad de resultados bajo condiciones repetidas especificadas.']], sequence:['definir referencia','sincronizar lectura','observar intervalo','calcular desviación','repetir condiciones','declarar alcance'], quantities:['segundos por día','desviación media','dispersión','intervalo de observación'], caseStudy:'Que un reloj marque la hora correcta al comenzar no dice su marcha. Que termine bien una vez puede ocultar compensaciones. Un informe defendible conserva posiciones, temperatura, estado de carga, duración y referencia.', failures:['Inferir estabilidad desde una coincidencia.','Usar cronómetro como sinónimo comercial de reloj preciso.'], misconception:{expression:'Si ahora coincide, está ajustado', correction:'una coincidencia no estima la deriva ni la variación entre condiciones.'}, transfer:'Diseña un registro de siete días que separe ajuste inicial, marcha y dispersión.' }),

  U({ route:'mechanical-energy-trains', slug:'toh-movimiento-simple', title:'Movimiento mecánico simple como sistema cerrado', question:'¿Cómo cooperan acumulador, tren, escape, regulador y visualización?', core:'El movimiento mecánico simple transforma energía potencial del muelle en una indicación regulada. El barrilete entrega par; el tren adapta velocidad y par; el escape alterna bloqueo e impulso; el volante-espiral determina la cadencia; la minutería escala la salida.', subsystem:'integration', sources:['source.private.toh.ch03','source.private.daniels.movement-design'], concepts:[['cadena energética','Ruta de almacenamiento, transmisión, dosificación y disipación de energía.'],['cadena informativa','Ruta por la que la cadencia del regulador determina el avance indicado.'],['estado de carga','Condición energética del muelle que modifica el par disponible.']], sequence:['dar cuerda','almacenar energía','transmitir por el tren','dosificar en el escape','mantener oscilación','contar e indicar'], quantities:['par del barrilete','relación del tren','frecuencia del volante','reserva de marcha'], caseStudy:'Si el escape queda bloqueado, el tren conserva energía pero no avanza. Si el volante oscila sin impulso, la indicación se detendrá al disiparse la energía. El síntoma final no identifica por sí solo el primer eslabón fallido.', failures:['Confundir movimiento visible con transmisión correcta.','Presentar el escape como fuente de energía.'], misconception:{expression:'El volante impulsa todo el tren', correction:'el muelle entrega energía y el regulador gobierna cuándo el escape libera el tren.'}, transfer:'Recorre la cadena hacia delante y hacia atrás para tres síntomas diferentes.', lab:{subsystem:'integration', commands:['wind','release','block','unblock','inspect','restore'], views:['energy-flow','kinematics','textual'], type:'energy-flow-diagram'} }),
  U({ route:'mechanical-energy-trains', slug:'toh-muelle-par', title:'Muelle real: energía, par y curva de entrega', question:'¿Por qué un muelle con más vueltas no entrega un par constante?', core:'El muelle real almacena energía al deformarse. Su momento depende de material, sección, longitud, curvatura, enrollamiento y fricción entre espiras y paredes. La zona útil de la curva se elige para evitar extremos de entrega y tensión.', subsystem:'barrel', sources:['source.private.toh.ch04','source.private.daniels.mainsprings'], concepts:[['curva de par','Relación entre estado de enrollamiento y momento entregado.'],['número de vueltas útiles','Intervalo de vueltas utilizado durante la marcha, menor que el rango geométrico total.'],['brida deslizante','Extremo exterior que limita la sobrecarga en muchos automáticos mediante deslizamiento controlado.']], sequence:['aplicar cuerda al árbol','enrollar el muelle','aumentar energía almacenada','liberar par al tambor','vencer pérdidas','alcanzar fin de reserva'], quantities:['espesor y altura','longitud','vueltas','par','energía'], caseStudy:'Dos muelles que caben en el mismo tambor pueden dar reservas y tensiones distintas. Elegir por diámetro exterior ignora sección, longitud, material, gancho y curva; una sustitución exige especificación o medición defendible.', failures:['Estimar el par solo por rigidez al tacto.','Llenar todo el barrilete para maximizar reserva.'], misconception:{expression:'Más muelle siempre significa mejor reserva', correction:'aumentar ocupación puede reducir espacio de respiración, elevar tensión y empeorar eficiencia.'}, transfer:'Compara dos diseños manteniendo volumen exterior y declara qué variables cambian.', lab:{subsystem:'barrel', commands:['wind','release','inspect','restore'], views:['section','energy-flow','textual'], type:'section-view'} }),
  U({ route:'mechanical-energy-trains', slug:'toh-barrilete-arquitecturas', title:'Barrilete, árbol, tambor y apoyos', question:'¿Qué interfaces convierten el muelle real en una fuente de par utilizable?', core:'El extremo interior se relaciona con el árbol y el exterior con tambor o pared según arquitectura. Tapa, fondo, pivotes, gancho, dentado y lubricación delimitan alineación, fricción y seguridad. Motor barrel y going barrel no transmiten de la misma manera.', subsystem:'barrel', sources:['source.private.toh.ch04','source.private.chicago.6'], concepts:[['going barrel','Arquitectura en la que gira el tambor dentado para impulsar el tren.'],['motor barrel','Arquitectura en la que la salida principal se toma de otro miembro del conjunto.'],['apoyo del árbol','Interfaz que centra el árbol y controla juego sin bloquearlo.']], sequence:['anclar extremo interior','guiar el árbol','contener espiras','cerrar tapa','transmitir al dentado','controlar juego y fricción'], quantities:['diámetro interior','juego axial','juego radial','altura disponible','par de salida'], caseStudy:'Un barrilete que gira libre vacío puede frenarse cargado si la tapa está deformada, el árbol inclinado o el muelle roza. La prueba debe reproducir estado de montaje y carga sin convertir una manipulación peligrosa en evidencia suficiente.', failures:['Comprobar solo el tambor vacío.','Abrir un barrilete sin determinar energía almacenada.'], misconception:{expression:'El barrilete es solo una caja para el muelle', correction:'sus apoyos y salida forman parte activa de la transmisión y condicionan el par.'}, transfer:'Dibuja interfaces y riesgos de dos arquitecturas de barrilete.', lab:{subsystem:'barrel', commands:['wind','rotate','inspect','restore'], views:['section','exploded','kinematics'], type:'exploded-view'} }),
  U({ route:'mechanical-energy-trains', slug:'toh-engranaje-geometria', title:'Geometría del engrane relojero', question:'¿Qué debe cumplirse para transmitir giro entre rueda y piñón sin interferencia destructiva?', core:'Número de dientes, módulo, diámetros, distancia entre centros, espesor y perfiles determinan el contacto. La relojería utiliza condiciones y perfiles que deben leerse en sus normas; un dibujo visualmente dentado no demuestra rodadura, penetración ni eficiencia.', subsystem:'gear-pair', sources:['source.private.toh.ch05','source.private.vba-uhrentechnik'], concepts:[['módulo','Relación normalizada entre diámetro primitivo y número de dientes.'],['distancia entre centros','Separación de ejes que sitúa los perfiles en su profundidad de trabajo.'],['arco de conducción','Intervalo durante el que un par de perfiles permanece en contacto funcional.']], sequence:['definir relación','seleccionar dientes','establecer módulo y perfiles','calcular centros','comprobar contacto','verificar bajo carga'], quantities:['z','m','diámetro primitivo','distancia entre centros','espesor de diente'], caseStudy:'Aumentar ligeramente la distancia entre centros puede reducir profundidad y provocar pérdida de conducción; reducirla puede causar penetración e interferencia. El efecto depende de perfil, dientes y errores reales, no de una regla visual única.', failures:['Usar diámetro exterior como primitivo.','Validar un engrane porque gira sin carga.'], misconception:{expression:'Si los dientes se tocan, engranan', correction:'el contacto debe seguir una geometría compatible, con profundidad, libertad y continuidad bajo carga.'}, transfer:'Calcula una pareja ideal, enumera hipótesis y define observaciones para diferenciar exceso y defecto de profundidad.', lab:{subsystem:'gear-pair', commands:['rotate','change-ratio','align','misalign','inspect','restore'], views:['schematic','kinematics','slow-motion','textual'], type:'kinematic-animation'} }),
  U({ route:'mechanical-energy-trains', slug:'toh-relaciones-tren', title:'Relaciones del tren y sentido de giro', question:'¿Cómo se calcula la frecuencia de una rueda a partir de ruedas y piñones sucesivos?', core:'Cada engrane externo invierte sentido y escala velocidad de acuerdo con dientes conductores y conducidos. En un tren compuesto, las relaciones se multiplican; una rueda y su piñón solidarios comparten velocidad angular. Contar etapas sin identificar pares produce resultados falsos.', subsystem:'train', sources:['source.private.toh.ch05','source.private.vba-uhrentechnik'], concepts:[['relación de transmisión','Cociente de velocidades determinado por los dientes efectivos de cada pareja.'],['tren compuesto','Cadena en la que rueda y piñón comparten eje para enlazar etapas.'],['sentido alternante','Inversión del giro producida por cada contacto exterior.']], sequence:['identificar conductor','identificar conducido','anotar dientes','calcular pareja','multiplicar etapas','comprobar frecuencia y sentido'], quantities:['dientes por móvil','revoluciones por hora','frecuencia de escape','sentido de giro'], caseStudy:'Una cuarta rueda de una vuelta por minuto no se obtiene imponiendo ese valor a una sola pareja; resulta del producto completo y de la frecuencia de escape. Una rueda intermedia puede cambiar sentido sin cambiar la magnitud global si no forma etapa compuesta.', failures:['Sumar relaciones de etapas.','Contar todas las ruedas como inversiones independientes sin distinguir elementos solidarios.'], misconception:{expression:'Dos etapas 4:1 dan 8:1', correction:'las relaciones de etapas sucesivas se multiplican y producen 16:1.'}, transfer:'Resuelve un tren hacia delante y después deduce dientes faltantes desde una frecuencia objetivo.', lab:{subsystem:'train', commands:['rotate','change-ratio','add-stage','remove-stage','inspect','restore'], views:['schematic','kinematics','textual'], type:'kinematic-animation'} }),
  U({ route:'mechanical-energy-trains', slug:'toh-potencia-tren', title:'Par, velocidad, potencia y pérdidas en el tren', question:'¿Por qué una relación cinemática correcta puede no mover el escape?', core:'La relación fija velocidades ideales, pero la potencia disponible se reduce por fricción, deformación, aceite, desalineación e impactos. Velocidad y par se intercambian dentro del balance energético; una obstrucción pequeña cerca del escape puede consumir el margen final.', subsystem:'train', sources:['source.private.toh.ch05','source.private.daniels.wheels-pinions'], concepts:[['rendimiento de etapa','Fracción de potencia de entrada que alcanza la salida.'],['margen de par','Diferencia entre par disponible y resistente en una condición.'],['pérdida parasitaria','Consumo de energía que no contribuye a la función deseada.']], sequence:['recibir par','transformar velocidad','vencer fricción de apoyos','transmitir por dientes','acumular pérdidas','entregar margen al escape'], quantities:['potencia P=Mω','rendimiento por etapa','par resistente','juego y alineación'], caseStudy:'Un tren puede caer libre parcialmente y detenerse montado por carga de puente, pivote doblado o aceite fuera de lugar. La prueba de giro aislada orienta, pero el diagnóstico exige condiciones de montaje y observación por etapas.', failures:['Atribuir todo frenado a dientes sucios.','Confundir relación correcta con potencia suficiente.'], misconception:{expression:'El tren no consume energía', correction:'cada apoyo y engrane disipa parte de la potencia y reduce el margen disponible.'}, transfer:'Construye un presupuesto cualitativo de pérdidas y diseña pruebas de localización.', lab:{subsystem:'train', commands:['rotate','misalign','introduce-fault','inspect','restore'], views:['energy-flow','kinematics','uncertainty'], type:'energy-flow-diagram'} }),
  U({ route:'mechanical-energy-trains', slug:'toh-minuteria-friccion', title:'Acoplamiento de minutería y ajuste manual', question:'¿Cómo puede el reloj indicar durante la marcha y permitir corregir las agujas sin romper el tren?', core:'La minutería toma una rotación del tren y la escala a minutos y horas. El acoplamiento de fricción permite arrastrar la indicación durante la puesta en hora y volver a transmitir durante la marcha. Su par debe superar la carga de agujas sin perturbar el tren.', subsystem:'motion-works', sources:['source.private.toh.ch05','source.private.chicago.9'], concepts:[['cañón de minutos','Elemento coaxial que transmite la indicación y suele proporcionar el acoplamiento de fricción.'],['rueda de minutería','Rueda intermediaria que participa en la relación entre minutos y horas.'],['par de arrastre','Par necesario para vencer la fricción y mover la indicación durante el ajuste.']], sequence:['tomar giro del tren','acoplar por fricción','mover minutera','reducir hacia rueda horaria','indicar horas','desacoplar manualmente al ajustar'], quantities:['relación 12:1','par de fricción','altura de cañones','holgura entre agujas'], caseStudy:'Una minutera que salta puede deberse a fricción insuficiente, ajuste de agujas, interferencia o dentado; una fricción excesiva puede robar amplitud. Apretar sin diagnosticar modifica una variable y puede dañar concentricidad.', failures:['Regular la fricción sin comprobar agujas.','Confundir puesta en hora con parada del tren.'], misconception:{expression:'La minutería está unida rígidamente al tren', correction:'necesita un acoplamiento que transmita en marcha y permita el ajuste manual.'}, transfer:'Compara dos ubicaciones del acoplamiento y analiza sus síntomas.', lab:{subsystem:'motion-works', commands:['set-time','engage','disengage','rotate','inspect','restore'], views:['kinematics','section','textual'], type:'kinematic-animation'} }),

  U({ route:'math-physics-metrology', slug:'toh-normas-dentado', title:'Normas, perfiles y lectura de tablas relojeras', question:'¿Cómo se transforma una tabla NHS/NIHS en una geometría calculable sin inventar datos?', core:'Una norma define símbolos, perfiles, coeficientes, condiciones y alcance. Antes de usar una fórmula se identifica edición, unidades y tipo de rueda o piñón. Diámetro exterior, primitivo y de pie no son intercambiables.', subsystem:'engineering-math', sources:['source.private.toh.ch05','source.private.vba-uhrentechnik'], concepts:[['norma dimensional','Regla publicada que fija definiciones y relaciones para una clase de componentes.'],['coeficiente de perfil','Factor adimensional que modifica una dimensión normalizada.'],['dominio de aplicación','Conjunto de dientes, perfiles y condiciones para los que una expresión es válida.']], sequence:['identificar norma','leer símbolos','confirmar unidades','seleccionar caso','calcular','verificar límites'], quantities:['módulo','número de dientes','coeficientes','diámetros calculados'], caseStudy:'Aplicar d=mz a un diámetro exterior produce error si d designa el primitivo. La ecuación puede ser correcta y la sustitución incorrecta; por eso cada variable conserva definición y figura.', failures:['Copiar fórmula sin leyenda.','Mezclar unidades o ediciones de tabla.'], misconception:{expression:'Una fórmula normativa vale para cualquier engrane', correction:'su validez está limitada por el perfil y las condiciones definidas.'}, transfer:'Crea una ficha de fórmula con símbolos, unidades, rango y caso de prueba.' }),
  U({ route:'math-physics-metrology', slug:'toh-contar-tren', title:'Diseño inverso de un tren de conteo', question:'¿Cómo se deduce una combinación de dientes desde la frecuencia del regulador y la indicación?', core:'El diseño inverso parte de oscilaciones, impulsos por oscilación, dientes de escape y salida deseada. La relación global se factoriza en etapas fabricables, evitando piñones inviables y conflictos de centros.', subsystem:'engineering-math', sources:['source.private.toh.ch05','source.private.vba-uhrentechnik'], concepts:[['relación objetivo','Cociente total necesario entre entrada regulada y salida indicada.'],['factorización de tren','Distribución de una relación global entre varias parejas de dientes.'],['restricción geométrica','Condición de tamaño, dientes o centros que limita soluciones matemáticas.']], sequence:['convertir frecuencia a impulsos','obtener vueltas del escape','fijar salida','calcular relación total','factorizar etapas','comprobar geometría'], quantities:['alternancias por hora','dientes de escape','vueltas por hora','producto de relaciones'], caseStudy:'Dos factorizaciones pueden producir la misma indicación pero exigir diámetros, piñones y centros distintos. La solución aritmética es solo candidata hasta verificar fabricabilidad y potencia.', failures:['Ignorar si el escape avanza un diente por ciclo o por alternancia.','Aceptar cualquier factorización entera.'], misconception:{expression:'La relación total determina un único tren', correction:'muchas combinaciones comparten relación y se eligen por geometría, potencia y arquitectura.'}, transfer:'Propón dos trenes para una misma frecuencia y compara compromisos.', lab:{subsystem:'train', commands:['change-ratio','add-stage','remove-stage','rotate','inspect','restore'], views:['schematic','kinematics','textual'], type:'virtual-instrument'} }),
  U({ route:'math-physics-metrology', slug:'toh-oscilador-modelo', title:'Modelo dinámico del volante-espiral', question:'¿Qué aproxima el oscilador armónico y dónde deja de describir un volante real?', core:'En primera aproximación la frecuencia depende de rigidez angular e inercia. Amplitud, geometría de espiral, fricción, escape, gravedad, temperatura y magnetismo introducen perturbaciones. El modelo normalizado sirve para razonar, no para declarar marcha de una unidad.', subsystem:'oscillator', sources:['source.private.toh.ch07','source.private.vba-uhrentechnik'], concepts:[['inercia del volante','Resistencia rotacional determinada por distribución de masa.'],['rigidez angular','Momento restaurador por unidad de desplazamiento angular.'],['amortiguamiento','Pérdida de energía que reduce amplitud si no existe mantenimiento.']], sequence:['desplazar volante','almacenar energía en espiral','cruzar equilibrio','intercambiar energía cinética','perder energía','recibir impulso'], quantities:['f aproximada','momento de inercia','rigidez','amplitud','factor de calidad'], caseStudy:'Reducir longitud activa eleva rigidez y normalmente aumenta frecuencia, pero un cambio real también altera centrado, curva y puntos de sujeción. El sentido cualitativo no basta para cuantificar marcha.', failures:['Calcular frecuencia sin unidades ni geometría.','Ignorar la perturbación del escape.'], misconception:{expression:'El volante oscila a una frecuencia fija por construcción', correction:'la frecuencia efectiva depende del conjunto y de perturbaciones, no solo del volante aislado.'}, transfer:'Modifica una variable cada vez y predice frecuencia y amplitud con límites.', lab:{subsystem:'oscillator', commands:['oscillate','set-hairspring-active-length','pause-oscillator','inspect','restore'], views:['slow-motion','kinematics','textual'], type:'kinematic-animation'} }),

  U({ route:'escapements-chronometry', slug:'toh-escape-fases', title:'Fases completas del escape de áncora suizo', question:'¿Qué estados atraviesa un diente desde el bloqueo hasta el siguiente bloqueo?', core:'El ciclo distingue reposo, despeje, impulso, caída y recorrido hacia bloqueo. Cada paleta alterna funciones y el volante solo interactúa durante una fracción de la oscilación. Nombrar fases permite diagnosticar sin reducirlo a dos piezas que chocan.', subsystem:'escapement', sources:['source.private.toh.ch06','source.private.bulova.10'], concepts:[['despeje','Movimiento que libera el diente de la superficie de bloqueo.'],['impulso','Contacto que transmite energía durante un arco definido.'],['caída','Movimiento libre de la rueda entre fin de impulso y nuevo bloqueo.']], sequence:['reposo en bloqueo','despeje por la clavija','impulso en paleta','liberación del diente','caída','nuevo bloqueo'], quantities:['bloqueo','caída','draw','arco de alzada','batido'], caseStudy:'Un escape puede arrancar y aun tener caída desigual, bloqueo inseguro o impulso deficiente. La observación lenta por fases evita declarar correcto el conjunto solo porque el volante oscila.', failures:['Confundir caída con juego de tren.','Ajustar una paleta sin comprobar la fase opuesta.'], misconception:{expression:'El escape solo bloquea y suelta', correction:'entre ambos estados existen despeje, impulso y caída con geometrías diferenciadas.'}, transfer:'Describe una vuelta de rueda diente a diente y marca dónde medirías cada condición.', lab:{subsystem:'escapement', commands:['step-escapement','scrub-escapement','set-escapement-speed','pause-escapement','inspect','restore'], views:['slow-motion','step-by-step','kinematics','textual'], type:'kinematic-animation'} }),
  U({ route:'escapements-chronometry', slug:'toh-seguridad-escape', title:'Seguridad: draw, guardia y cuernos', question:'¿Cómo evita el escape una liberación accidental cuando el reloj recibe perturbaciones?', core:'Draw mantiene el áncora apoyada contra los topes; dardo, platillo de seguridad y cuernos limitan relaciones no deseadas fuera del arco de desbloqueo. Las holguras deben permitir el ciclo sin perder protección.', subsystem:'escapement', sources:['source.private.toh.ch06','source.private.bulova.10'], concepts:[['draw','Componente geométrica que lleva el áncora hacia el tope durante el bloqueo.'],['acción de guardia','Interacción que impide el desplazamiento indebido del áncora fuera de fase.'],['run to banking','Recorrido disponible desde el bloqueo hasta el apoyo en el tope.']], sequence:['diente bloqueado','draw asienta áncora','golpe intenta desplazarla','guardia limita movimiento','clavija entra en fase','despeje autorizado'], quantities:['holgura de guardia','profundidad de bloqueo','run','distancia a topes'], caseStudy:'Reducir una holgura puede aumentar roce; aumentarla puede perder seguridad. Una comprobación estática debe completarse con secuencia y condiciones documentadas, sin deformar componentes por tanteo.', failures:['Eliminar juego para obtener seguridad.','Confundir topes con ajuste de marcha.'], misconception:{expression:'Cuanto más apretado, más seguro', correction:'la seguridad requiere holguras funcionales equilibradas, no ausencia de libertad.'}, transfer:'Compara fallo por exceso y defecto de cada holgura.', lab:{subsystem:'escapement', commands:['step-escapement','introduce-fault','inspect','restore'], views:['step-by-step','uncertainty','textual'], type:'error-simulation'} }),
  U({ route:'escapements-chronometry', slug:'toh-volante-espiral-conjunto', title:'Volante, espiral, pitón, virola y raqueta', question:'¿Qué hace cada interfaz del órgano regulador y cómo altera su comportamiento?', core:'La virola fija el extremo interior; el pitón fija el exterior; la raqueta modifica longitud activa en sistemas regulados. Plano, centrado, respiración y libertad respecto a pasadores afectan simetría e isocronismo.', subsystem:'oscillator', sources:['source.private.toh.ch07','source.private.bulova.06'], concepts:[['virola','Elemento que une el extremo interior de la espiral al eje del volante.'],['pitón','Sujeción del extremo exterior al puente o portapitón.'],['longitud activa','Tramo efectivo de espiral que participa en la rigidez oscilatoria.']], sequence:['fijar interior','formar espiras','guiar exterior','pasar entre clavijas','fijar pitón','respirar sin contacto'], quantities:['plano','concentricidad','separación entre espiras','longitud activa','batido'], caseStudy:'Una espiral centrada en reposo puede desplazarse al respirar y tocar raqueta o puente. La inspección debe observar amplitudes y orientaciones, no solo una fotografía inmóvil.', failures:['Corregir marcha doblando sin diagnosticar.','Juzgar centrado solo en reposo.'], misconception:{expression:'La espiral solo necesita verse redonda', correction:'debe respirar con simetría, plano, centrado y libertad funcional.'}, transfer:'Diseña una secuencia de observación que no confunda forma estática y respiración.', lab:{subsystem:'oscillator', commands:['oscillate','set-hairspring-active-length','inspect','restore'], views:['slow-motion','section','textual'], type:'kinematic-animation'} }),
  U({ route:'escapements-chronometry', slug:'toh-isocronismo', title:'Isocronismo y dependencia de amplitud', question:'¿Por qué el periodo puede cambiar cuando cambia la amplitud?', core:'El modelo armónico ideal es isócrono, pero geometría de espiral, puntos de fijación, gravedad, escape, fricción y elasticidad introducen errores. Comparar marcha a distintas amplitudes revela la suma del sistema, no una causa única.', subsystem:'chronometry', sources:['source.private.toh.ch07','source.private.daniels.balance-spring'], concepts:[['error de isocronismo','Variación de periodo asociada al cambio de amplitud o energía.'],['efecto Caspari','Dependencia teórica vinculada a la posición de fijación exterior y geometría.'],['efecto Grossmann','Componente del error relacionada con configuración y fijación de la espiral.']], sequence:['cambiar par disponible','cambiar amplitud','alterar respiración efectiva','modificar perturbaciones','cambiar periodo','observar marcha'], quantities:['amplitud','marcha','reserva transcurrida','posición','temperatura'], caseStudy:'Una marcha estable a plena cuerda puede degradarse al final de reserva. Antes de culpar a la espiral se comparan par, amplitud, escape, fricción y condiciones; el patrón orienta pero no identifica por sí solo.', failures:['Ajustar raqueta para corregir una curva de amplitud.','Atribuir isocronismo solo al material de espiral.'], misconception:{expression:'La frecuencia del volante no depende de la amplitud', correction:'la independencia es una aproximación ideal y el conjunto real introduce términos dependientes.'}, transfer:'Construye una matriz de marcha frente a amplitud y reserva y propón pruebas discriminantes.', lab:{subsystem:'oscillator', commands:['oscillate','set-hairspring-active-length','introduce-fault','inspect','restore'], views:['kinematics','uncertainty','textual'], type:'virtual-instrument'} }),
  U({ route:'escapements-chronometry', slug:'toh-posiciones-perturbaciones', title:'Posiciones, gravedad, poising y perturbaciones', question:'¿Por qué un reloj cambia de marcha al cambiar de orientación?', core:'En horizontal dominan unos apoyos; en vertical cambian contactos, flexiones y efecto de desequilibrio. Poising estático, poising dinámico, centrado de espiral, pivotes, antichoque y magnetismo pueden producir patrones distintos.', subsystem:'chronometry', sources:['source.private.toh.ch07','source.private.bulova.05'], concepts:[['error posicional','Diferencia sistemática de marcha entre orientaciones declaradas.'],['poising estático','Equilibrio del volante en reposo respecto a gravedad.'],['poising dinámico','Distribución efectiva durante oscilación, no demostrada solo por reposo.']], sequence:['orientar movimiento','cambiar apoyos activos','aplicar gravedad al desequilibrio','modificar fricción y respiración','observar señal','comparar patrón'], quantities:['marcha por posición','amplitud','beat error','orientación','duración'], caseStudy:'Un punto pesado puede afectar de forma diferente según orientación y amplitud. Pero un patrón similar puede proceder de espiral descentrada o pivote; se necesitan observaciones correlacionadas.', failures:['Corregir masa antes de inspeccionar espiral y pivotes.','Medir posiciones con estados de carga distintos.'], misconception:{expression:'Toda diferencia vertical es un volante desequilibrado', correction:'varias interfaces sensibles a gravedad producen patrones posicionales.'}, transfer:'Propón un orden de pruebas de menor a mayor intervención.' }),
  U({ route:'escapements-chronometry', slug:'toh-tourbillon-carrusel', title:'Tourbillon, carrusel y promedio posicional', question:'¿Qué error intentan promediar los reguladores rotatorios y qué no corrigen?', core:'Al rotar escape y regulador se transforman errores dependientes de orientación en una contribución promediada durante el ciclo. Tourbillon y carrusel difieren en arquitectura de accionamiento. No eliminan fricción, isocronismo, temperatura ni defectos geométricos.', subsystem:'rotating-regulator', sources:['source.private.toh.ch07','source.private.daniels.escapements'], concepts:[['jaula','Estructura rotatoria que porta parte del regulador y escape.'],['periodo de rotación','Tiempo de una vuelta completa del conjunto rotatorio.'],['promedio posicional','Reducción de una componente de error al recorrer orientaciones.']], sequence:['accionar jaula','cambiar orientación relativa','muestrear error posicional','integrar durante vuelta','obtener promedio','mantener errores no correlacionados'], quantities:['periodo de jaula','masa e inercia','consumo de par','patrón posicional'], caseStudy:'Una jaula de un minuto no garantiza exactitud: puede promediar un error y a la vez exigir energía, rigidez y fabricación adicionales. El rendimiento se demuestra midiendo, no contando componentes.', failures:['Presentarlo como anulación de gravedad.','Confundir carrusel y tourbillon por apariencia.'], misconception:{expression:'El tourbillon elimina los errores de posición', correction:'solo puede promediar ciertas componentes bajo condiciones y añade sus propios compromisos.'}, transfer:'Compara una arquitectura fija y otra rotatoria mediante presupuesto de error.' }),

  U({ route:'complications', slug:'toh-automatico-rotor', title:'Rotor, masa excéntrica y captación de movimiento', question:'¿Cómo transforma un rotor movimientos irregulares de la muñeca en cuerda acumulada?', core:'La masa excéntrica genera movimiento relativo; rodamientos o apoyos lo guían; engranajes y reversores rectifican uno o ambos sentidos; el sistema limita sobrecarga mediante la arquitectura del barrilete.', subsystem:'automatic', sources:['source.private.toh.ch08','source.private.chicago.6'], concepts:[['masa oscilante','Rotor con centro de masa desplazado que responde a aceleraciones.'],['rectificación mecánica','Conversión de giros alternos en un sentido útil de cuerda.'],['rendimiento de carga','Fracción del movimiento captado que termina como energía almacenada.']], sequence:['mover caja','rotar masa','transmitir a reversor','rectificar sentido','reducir y aumentar par','cargar muelle'], quantities:['momento del rotor','umbral de arranque','relación','tasa de carga','pérdidas'], caseStudy:'Un rotor que gira libre no demuestra que cargue: puede fallar el acoplamiento, reversor o brida. La prueba debe observar incremento de estado de carga bajo un protocolo, no solo movimiento visible.', failures:['Asociar ruido de rotor con carga eficaz.','Evaluar automático sin estado inicial.'], misconception:{expression:'Todo giro del rotor da cuerda', correction:'solo el giro transmitido y rectificado que supera pérdidas alcanza el barrilete.'}, transfer:'Compara sistemas uni y bidireccionales con el mismo protocolo.', lab:{subsystem:'automatic', commands:['enable-automatic','rotate','disable-automatic','inspect','restore'], views:['kinematics','energy-flow','textual'], type:'kinematic-animation'} }),
  U({ route:'complications', slug:'toh-reversores-deslizamiento', title:'Reversores, desacoplamiento y limitación de carga', question:'¿Cómo evita un automático transmitir en sentido incorrecto o sobrecargar el muelle?', core:'Ruedas inversoras, trinquetes o embragues seleccionan caminos de par. Cuando el muelle alcanza su rango, una brida puede deslizar de forma controlada. Suciedad, aceite incorrecto o desgaste pueden producir patinamiento prematuro o bloqueo.', subsystem:'automatic', sources:['source.private.toh.ch08','source.private.daniels.mainsprings'], concepts:[['rueda inversora','Conjunto que transmite uno de los sentidos y desacopla el contrario.'],['desacoplamiento','Estado que interrumpe una ruta de par para evitar arrastre inverso.'],['par de deslizamiento','Umbral a partir del cual la brida exterior se desplaza en la pared.']], sequence:['recibir giro alterno','seleccionar camino','bloquear sentido útil','liberar retorno','cargar barrilete','deslizar al alcanzar umbral'], quantities:['par de arranque','par de deslizamiento','tasa de carga','reserva inicial y final'], caseStudy:'Un reloj que no alcanza reserva puede tener poca actividad, reversores ineficientes, brida que desliza pronto o consumo elevado. Cada hipótesis exige una observación distinta y estado inicial controlado.', failures:['Lubricar reversores por intuición.','Concluir brida gastada sin medir carga.'], misconception:{expression:'El automático deja de girar cuando está cargado', correction:'muchas arquitecturas permiten que el rotor siga moviéndose mientras la brida limita la carga.'}, transfer:'Diseña pruebas que separen captación, transmisión, deslizamiento y consumo.', lab:{subsystem:'automatic', commands:['enable-automatic','engage','disengage','rotate','introduce-fault','inspect','restore'], views:['kinematics','uncertainty','textual'], type:'error-simulation'} }),
  U({ route:'complications', slug:'toh-calendario-secuencia', title:'Calendario simple, salto y corrección', question:'¿Cómo acumula un calendario un ciclo diario y lo transforma en avance discreto?', core:'Una rueda de arrastre toma la rotación diaria, carga o empuja un mecanismo de cambio, libera el disco y un muelle de posicionamiento lo estabiliza. La corrección rápida puede compartir piezas y crear una zona temporal de riesgo.', subsystem:'calendar', sources:['source.private.toh.ch09','source.official.eta.2824'], concepts:[['arrastre de fecha','Interfaz que transmite el ciclo horario al indicador.'],['salto de calendario','Transición discreta entre posiciones legibles.'],['jumper','Muelle o pieza que posiciona el disco y resiste movimientos intermedios.']], sequence:['tomar ciclo de 24 horas','aproximar arrastre','cargar o empujar','vencer jumper','avanzar un paso','asentar nueva fecha'], quantities:['relación diaria','duración de cambio','par del jumper','zona de engrane'], caseStudy:'Corregir la fecha durante el engrane puede enfrentar la corrección manual con el arrastre automático. La zona exacta depende del calibre y solo la documentación aplicable permite fijarla.', failures:['Publicar una franja horaria universal.','Girar el disco para comprobar sin identificar dependencias.'], misconception:{expression:'La fecha cambia instantáneamente a medianoche en todos los relojes', correction:'la fase, duración y arquitectura del cambio dependen del mecanismo.'}, transfer:'Compara cambio progresivo e instantáneo y declara riesgos de servicio.', lab:{subsystem:'calendar', commands:['advance-calendar','change-crown-position','introduce-fault','inspect','restore'], views:['step-by-step','kinematics','textual'], type:'kinematic-animation'} }),
  U({ route:'complications', slug:'toh-calendario-perpetuo', title:'Calendarios completo, anual y perpetuo', question:'¿Qué memoria mecánica necesita un reloj para resolver meses desiguales y años bisiestos?', core:'Un calendario simple cuenta hasta 31; mecanismos más complejos codifican longitud de mes y, en el perpetuo, el ciclo de cuatro años con excepciones seculares normalmente fuera de su horizonte. Levas, ruedas programa y palancas almacenan estado mecánico.', subsystem:'calendar', sources:['source.private.toh.ch09','source.private.daniels.movement-design'], concepts:[['rueda programa','Componente que codifica una secuencia de longitudes de mes.'],['gran palanca','Elemento lector que integra estados del programa para gobernar correcciones.'],['ciclo bisiesto','Estado de cuatro años usado para insertar febrero de 29 días.']], sequence:['contar días','leer programa mensual','detectar fin de mes','saltar días inexistentes','actualizar mes','actualizar ciclo anual'], quantities:['31 posiciones','12 meses','ciclo de 4 años','reserva de par para cambio'], caseStudy:'Una indicación perpetua puede desincronizarse si se corrige una variable sin respetar el estado conjunto. El diagnóstico comienza registrando todas las indicaciones y la fase, no forzando hasta que coincidan.', failures:['Llamar perpetuo a todo calendario completo.','Ajustar cada disco como independiente.'], misconception:{expression:'Un calendario perpetuo conoce la fecha', correction:'codifica un ciclo mecánico finito y depende de estado inicial, continuidad y reglas incorporadas.'}, transfer:'Representa la memoria necesaria para simple, anual y perpetuo.' }),

  U({ route:'complications', slug:'toh-soneria-control', title:'Alarma, sonería y repetición a demanda', question:'¿Cómo separan estos mecanismos almacenamiento, lectura de hora, control y producción de sonido?', core:'La alarma libera energía en un instante programado; la repetición lee el estado horario al activarse y gobierna golpes mediante caracoles, rastrillos y sorpresa. Barrilete, regulador de sonería, martillos y timbres forman una cadena paralela.', subsystem:'striking', sources:['source.private.toh.ch10','source.private.daniels.movement-design'], concepts:[['rastrillo','Palanca dentada cuya caída codifica un número de golpes.'],['caracol','Leva escalonada que representa horas, cuartos o minutos.'],['pieza sorpresa','Elemento que estabiliza la lectura de minutos durante la transición horaria.']], sequence:['cargar sonería','solicitar o alcanzar disparo','leer estado','liberar tren','regular cadencia','golpear timbres'], quantities:['número de golpes','cadencia','reserva dedicada','secuencia horas-cuartos-minutos'], caseStudy:'Una repetición que da bien horas pero mal minutos puede tener lectura, sorpresa, rastrillo o secuencia afectados. El sonido final debe descomponerse por subcadenas antes de intervenir.', failures:['Confundir repetidor con alarma.','Diagnosticar por sonido sin registrar secuencia.'], misconception:{expression:'La sonería lee directamente las agujas', correction:'normalmente lee estados mecánicos mediante levas y palancas, no la posición visual de las agujas.'}, transfer:'Decodifica tres secuencias sonoras y localiza qué lector gobierna cada grupo.' }),
  U({ route:'complications', slug:'toh-cronografo-estados', title:'Cronógrafo: mando, embrague, freno y puesta a cero', question:'¿Qué estados deben coordinarse para iniciar, detener y volver a cero sin conflicto?', core:'El órgano de mando selecciona estados; el embrague conecta el contador al tren; el freno inmoviliza; martillos y corazones restauran cero. Rueda de pilares o leva coordinan secuencias, pero no son el embrague.', subsystem:'chronograph', sources:['source.private.toh.ch11','source.official.eta.7750'], concepts:[['órgano de mando','Sistema que transforma pulsaciones en estados ordenados.'],['embrague de cronógrafo','Interfaz que conecta o desconecta el contador del tren.'],['corazón de puesta a cero','Leva que conduce el indicador a una posición estable al recibir el martillo.']], sequence:['recibir pulsación','cambiar estado de mando','liberar freno','acoplar contador','detener y frenar','desacoplar y poner a cero'], quantities:['profundidad de acoplamiento','caída de martillo','desplazamiento de aguja','amplitud con cronógrafo'], caseStudy:'Una aguja que salta al arrancar puede relacionarse con profundidad lateral, dientes, fricción o posición; una amplitud que cae exige cuantificar carga. Cambiar excéntricas sin mapa de estados mezcla causas.', failures:['Llamar rueda de pilares al cronógrafo completo.','Poner a cero mientras sigue acoplado si la arquitectura no lo permite.'], misconception:{expression:'La rueda de pilares transmite el tiempo medido', correction:'coordina estados; la energía y el conteo viajan por el embrague y el tren cronográfico.'}, transfer:'Dibuja la máquina de estados de un sistema por leva y otro por rueda de pilares.' }),

  U({ route:'cases-water', slug:'toh-exterior-interfaces', title:'Exterior del reloj como cadena de interfaces', question:'¿Cómo relaciona la caja movimiento, esfera, agujas, cristal, mandos y correa?', core:'El exterior protege, posiciona, permite lectura y transmite acciones. Asientos, anillos, tija, tubo, corona, juntas, bisel, fondo y fijaciones construyen una pila axial y radial. Cambiar una interfaz puede alterar varias holguras.', subsystem:'case', sources:['source.private.toh.ch12','source.private.daniels.casemaking'], concepts:[['pila axial','Secuencia de alturas y separaciones desde fondo hasta cristal.'],['interfaz radial','Ajuste que centra o retiene componentes alrededor del eje del movimiento.'],['envolvente funcional','Volumen reservado para movimiento, agujas, esfera y desplazamientos.']], sequence:['posicionar movimiento','fijar esfera','montar agujas','reservar holgura','cerrar cristal y fondo','transmitir mando por tija'], quantities:['altura de movimiento','altura de cañones','holgura de agujas','diámetros de asiento','compresión de junta'], caseStudy:'Un cristal compatible en diámetro puede interferir con agujas por altura; una tija correcta puede quedar corta si cambia anillo o corona. La compatibilidad se demuestra en el mapa de interfaces, no por una medida aislada.', failures:['Elegir cristal solo por diámetro.','Ajustar tija antes de fijar posición del movimiento.'], misconception:{expression:'La caja es independiente del movimiento', correction:'sus cotas y mandos forman interfaces directas con movimiento, esfera e indicación.'}, transfer:'Construye una pila de cotas y marca cada criterio de verificación.' }),
  U({ route:'cases-water', slug:'toh-materiales-exterior', title:'Materiales, cristales, juntas y fijaciones exteriores', question:'¿Qué propiedades gobiernan selección, montaje y envejecimiento del exterior?', core:'Dureza, tenacidad, elasticidad, corrosión, transparencia, compatibilidad química y acabado condicionan caja, cristal, juntas y brazalete. La misma geometría nominal no garantiza igual comportamiento de montaje.', subsystem:'case', sources:['source.private.toh.ch12','source.official.bipm.vim'], concepts:[['compatibilidad material','Ausencia demostrada de interacción perjudicial entre materiales y productos.'],['deformación de junta','Cambio controlado de forma que produce contacto de sellado.'],['asiento funcional','Superficie cuya geometría y acabado participan en retención o sellado.']], sequence:['identificar material','definir carga y entorno','seleccionar ajuste','preparar asiento','montar sin daño','verificar función'], quantities:['dureza','módulo elástico','rugosidad','compresión','dilatación'], caseStudy:'Sustituir una junta por otra del mismo diámetro pero distinta sección o compuesto cambia compresión y fricción. La prueba de presión evalúa el conjunto y no corrige una selección sin datos.', failures:['Reutilizar juntas por buen aspecto.','Pulir una superficie de sellado sin medir geometría.'], misconception:{expression:'Una junta nueva garantiza estanqueidad', correction:'el resultado depende de material, sección, asiento, compresión, montaje y prueba.'}, transfer:'Compara dos materiales de cristal y dos de junta mediante propiedades y modos de fallo.' }),

  U({ route:'service-tribology', slug:'toh-friccion-desgaste', title:'Fricción, desgaste y regímenes de contacto', question:'¿Cómo se relacionan carga, velocidad, superficie y lubricante en un contacto relojero?', core:'La fricción no es una propiedad fija de una pieza: emerge del par de materiales, topografía, carga, movimiento, ambiente y lubricación. Adhesión, abrasión, fatiga y corrosión dejan firmas diferentes.', subsystem:'tribology', sources:['source.private.toh.ch13','source.private.daniels.jewelling'], concepts:[['par tribológico','Dos superficies y sus condiciones de contacto consideradas como sistema.'],['desgaste adhesivo','Transferencia o arranque asociado a uniones locales entre superficies.'],['desgaste abrasivo','Pérdida producida por asperezas o partículas que cortan o surcan.']], sequence:['aplicar carga','establecer contacto','mover superficies','formar o romper película','disipar energía','acumular desgaste'], quantities:['carga de contacto','velocidad','área efectiva','rugosidad','viscosidad'], caseStudy:'Un pivote rayado y un rubí contaminado pueden elevar fricción; pulir el pivote sin identificar diámetro, forma y daño puede reducir apoyo o enmascarar desgaste. Se registra antes de corregir.', failures:['Llamar suciedad a todo residuo oscuro.','Pulir hasta que brille sin criterio dimensional.'], misconception:{expression:'El rubí elimina la fricción', correction:'reduce y estabiliza ciertas condiciones, pero el contacto sigue dependiendo de geometría, carga, superficie y lubricación.'}, transfer:'Clasifica imágenes de daño como hipótesis y propone observaciones discriminantes.' }),
  U({ route:'service-tribology', slug:'toh-lubricacion-retencion', title:'Lubricación, cantidad y retención del aceite', question:'¿Por qué producto correcto y cantidad correcta son decisiones separadas?', core:'Viscosidad, capilaridad, tensión superficial, afinidad y geometría determinan dónde permanece un lubricante. Exceso puede migrar y contaminar; defecto deja contacto sin película. El mapa punto-producto-cantidad procede del fabricante o de una fuente aplicable.', subsystem:'lubrication', sources:['source.private.toh.ch13','source.institutional.awci.standards'], concepts:[['retención capilar','Permanencia de fluido condicionada por geometría y fuerzas superficiales.'],['mapa de lubricación','Relación trazable entre punto, producto, cantidad, método y fuente.'],['migración','Desplazamiento no deseado del lubricante hacia superficies vecinas.']], sequence:['identificar contacto','consultar fuente','limpiar y verificar','depositar cantidad','observar menisco o punto','controlar migración'], quantities:['viscosidad','volumen aplicado','diámetro de aceitador','temperatura','tiempo'], caseStudy:'Una fotografía histórica puede mostrar dónde se aceitaba, pero no autoriza un producto moderno ni cantidad. El procedimiento se bloquea hasta tener documentación del calibre y compatibilidad.', failures:['Lubricar para solucionar un defecto geométrico.','Mezclar productos o completar aceite antiguo.'], misconception:{expression:'Más aceite protege mejor', correction:'el exceso puede aumentar arrastre, migrar y contaminar escape, espiral o esfera.'}, transfer:'Construye un mapa de lubricación vacío que obligue a citar fuente antes de completar cada punto.' }),

  U({ route:'quartz-electronics', slug:'toh-cuarzo-oscilador-divisor', title:'Oscilador de cuarzo y división de frecuencia', question:'¿Cómo se transforma la resonancia de alta frecuencia en un pulso temporal lento?', core:'El resonador piezoeléctrico forma parte de un oscilador electrónico; su señal se divide mediante etapas binarias hasta obtener una cadencia de actuación. Frecuencia nominal, carga, temperatura, consumo y envejecimiento condicionan el resultado.', subsystem:'electronic-control', sources:['source.private.toh.ch15','source.official.miyota.2035'], concepts:[['resonancia de cuarzo','Respuesta mecanoeléctrica estable alrededor de una frecuencia determinada.'],['divisor binario','Cadena que reduce frecuencia por factores sucesivos de dos.'],['capacitancia de carga','Condición eléctrica que participa en la frecuencia efectiva del oscilador.']], sequence:['alimentar circuito','excitar resonador','sostener oscilación','formar señal','dividir frecuencia','emitir pulso'], quantities:['32768 Hz como arquitectura común, no universal','tensión','corriente','desviación de frecuencia'], caseStudy:'Una bobina sin pulsos puede deberse a alimentación, resonador, circuito o división. Medir continuidad de bobina solo comprueba el actuador y no demuestra referencia temporal.', failures:['Medir frecuencia sin carga adecuada.','Llamar cristal al circuito completo.'], misconception:{expression:'El cuarzo envía un pulso por segundo', correction:'el resonador oscila a frecuencia alta y el circuito divide la señal.'}, transfer:'Dibuja una cadena de diagnóstico desde célula hasta pulso de bobina.' }),
  U({ route:'quartz-electronics', slug:'toh-motor-paso-bipolar', title:'Bobina, estator y motor paso a paso bipolar', question:'¿Cómo produce un pulso eléctrico un giro discreto y orientado?', core:'La bobina magnetiza un circuito de estator; la polaridad y geometría crean un estado energético que hace avanzar el rotor imantado. Pulsos alternos y asimetrías controladas favorecen el siguiente paso. El tren recibe incrementos, no giro continuo.', subsystem:'stepper-motor', sources:['source.private.toh.ch15','source.official.miyota.2035'], concepts:[['estator','Circuito magnético fijo que conduce el flujo de la bobina.'],['rotor imantado','Elemento móvil con polos permanentes que busca una orientación energética.'],['pulso bipolar','Excitación cuya polaridad alterna para gobernar pasos sucesivos.']], sequence:['aplicar pulso','crear flujo en estator','desestabilizar rotor','girar hacia nuevo mínimo','transferir al piñón','invertir siguiente pulso'], quantities:['amplitud y duración de pulso','resistencia de bobina','par de paso','carga del tren'], caseStudy:'Un rotor que vibra sin completar paso puede tener carga mecánica, impulso insuficiente, geometría magnética o daño. Forzarlo con herramienta no distingue causas y puede desmagnetizar o dañar pivotes.', failures:['Alimentar bobina sin límites documentados.','Concluir circuito sano porque hay sonido.'], misconception:{expression:'La bobina gira', correction:'la bobina crea flujo; el rotor imantado es el elemento que cambia de orientación.'}, transfer:'Compara motor bipolar y de dos fases por entradas, estados y observaciones.' }),
  U({ route:'quartz-electronics', slug:'toh-cadena-electronica-completa', title:'Cadena completa del reloj electrónico analógico', question:'¿Cómo se diagnostica sin mezclar energía, referencia, lógica, actuación y mecánica?', core:'La célula y contactos suministran tensión; el oscilador crea referencia; la lógica divide y controla; el driver excita bobina; el motor convierte; el tren transmite; la indicación presenta. Cada frontera admite pruebas con autoridad y riesgo distintos.', subsystem:'quartz-integration', sources:['source.private.toh.ch15','source.official.miyota.2035'], concepts:[['driver','Etapa electrónica que entrega a la bobina la forma de pulso requerida.'],['consumo funcional','Corriente asociada al estado operativo bajo condiciones definidas.'],['frontera electro-mecánica','Interfaz donde el campo magnético se convierte en desplazamiento del rotor.']], sequence:['entregar energía','generar referencia','dividir y decidir','excitar bobina','avanzar rotor','transmitir e indicar'], quantities:['tensión bajo carga','consumo','frecuencia','resistencia de bobina','par resistente'], caseStudy:'Cambiar pila puede restaurar temporalmente un reloj con consumo anormal; que funcione no cierra diagnóstico. Se registra tensión, consumo, pulso y libertad mecánica según documentación.', failures:['Sustituir circuito antes de aislar carga.','Aplicar valores de un calibre a otro.'], misconception:{expression:'Un cuarzo parado tiene un problema eléctrico', correction:'la cadena termina en un tren mecánico susceptible de bloqueo y carga.'}, transfer:'Construye un árbol de pruebas de menor a mayor intervención.' }),
]

const BULOVA_UNITS = [
  U({ route:'workshop-tools-materials', slug:'bulova-destreza-basica', title:'Pasaporte de banco I: lupa, pinzas y destornillador', question:'¿Qué evidencia demuestra manipulación básica antes de tocar un movimiento?', core:'La destreza comienza por postura estable, visión alineada, apoyo de manos, selección de punta y control de fuerza. El ejercicio histórico de colocar tornillos se conserva como progresión: la competencia se evalúa por daño, pérdidas, control y repetibilidad, no por completar una vez.', subsystem:'bench-skill', sources:['source.private.bulova.preliminary','source.private.chicago.1'], concepts:[['agarre controlado','Sujeción suficiente para gobernar una pieza sin deformarla ni lanzarla.'],['alineación de herramienta','Coincidencia entre eje de fuerza, ranura o punto de contacto y trayectoria deseada.'],['criterio de parada','Condición observable que obliga a detener la operación antes del daño.']], sequence:['preparar zona','ajustar postura y luz','seleccionar herramienta','tomar pieza','posicionar sin arrastre','soltar y verificar'], quantities:['número de repeticiones','piezas perdidas','marcas y rebabas','tiempo sin sacrificar calidad'], caseStudy:'Una serie rápida con dos tornillos marcados no supera una serie lenta sin daño. Primero se estabiliza calidad; después se registra tiempo como resultado secundario.', failures:['Apretar pinzas para compensar mala alineación.','Usar una punta que no llena la ranura.'], misconception:{expression:'La destreza es trabajar rápido', correction:'la velocidad solo cuenta después de trazabilidad, control y ausencia de daño.'}, transfer:'Repite con tres tamaños de pieza y conserva fotografía antes/después y registro de errores.' }),
  U({ route:'workshop-tools-materials', slug:'bulova-evaluacion-destreza', title:'Pasaporte de banco II: repetición, calidad y revisión', question:'¿Cómo se convierte una operación manual en evidencia revisable?', core:'La práctica deliberada fija una operación, criterio, número de intentos, variación y revisión. Fotografías, conteo de errores, estado de herramienta y observación humana permiten separar finalización de competencia. La simulación prepara decisiones pero no acredita tacto.', subsystem:'bench-assessment', sources:['source.private.bulova.preliminary','source.institutional.awci.standards'], concepts:[['pasaporte de destreza','Registro longitudinal de operaciones, condiciones, evidencias y revisiones.'],['intento independiente','Ejecución sin ayuda sustantiva tras retirar guía.'],['defecto observable','Resultado visible o medible que contradice un criterio de calidad.']], sequence:['definir criterio','registrar estado inicial','ejecutar serie guiada','reducir ayuda','ejecutar independiente','revisar y programar retención'], quantities:['repeticiones','tasa de defectos','sesiones distintas','intervalo de retención'], caseStudy:'Completar cincuenta colocaciones con ayuda continua demuestra exposición. Para acreditar progreso se exige una serie independiente, fotografías, ausencia de daño y repetición posterior.', failures:['Promediar defectos graves con intentos correctos.','Conceder dominio desde una simulación.'], misconception:{expression:'Si la app marca completado, ya sé hacerlo', correction:'la app acredita conocimiento o evidencia registrada; la competencia física requiere operación real y revisión.'}, transfer:'Define criterios y evidencia para una segunda operación sin reutilizar umbrales no justificados.' }),
  U({ route:'micromechanics', slug:'bulova-botador-eje', title:'Pasaporte III: botador y sustitución de eje', question:'¿Qué referencias deben protegerse al separar y montar volante, platillo y eje?', core:'El botador aplica fuerza axial mediante punzón y asiento compatibles. Orientación, apoyo, diámetro, limpieza y secuencia evitan deformar llanta, platillo o remache. El procedimiento histórico se estudia como mapa; la ejecución exige pieza de práctica y supervisión.', subsystem:'staking', sources:['source.private.bulova.01','source.private.chicago.15'], concepts:[['apoyo de trabajo','Superficie que recibe la reacción sin cargar una zona frágil.'],['punzón compatible','Herramienta cuya forma y diámetro transmiten fuerza en la región prevista.'],['remachado concéntrico','Deformación controlada que fija sin desplazar el eje respecto al volante.']], sequence:['documentar orientación','seleccionar asiento','alinear conjunto','separar axialmente','inspeccionar referencias','montar y verificar'], quantities:['diámetros de apoyo','altura de hombros','concentricidad','alabeo posterior'], caseStudy:'Un punzón demasiado grande puede apoyar en la llanta; uno pequeño puede marcar el eje. La selección se demuestra por mapa de cargas antes de golpear.', failures:['Golpear con la pieza sin apoyo completo.','Corregir alabeo generado sin investigar montaje.'], misconception:{expression:'El botador garantiza que el golpe sea recto', correction:'solo lo facilita; asiento, punzón, alineación y técnica determinan la carga real.'}, transfer:'Planifica desmontaje en una pieza de práctica y somete la selección de apoyos a revisión.' }),
  U({ route:'micromechanics', slug:'bulova-torneado-fundamental', title:'Pasaporte IV: torneado entre puntos y buril', question:'¿Qué hábitos producen una superficie concéntrica sin convertir el torno en un riesgo?', core:'Preparación de centros, apoyo del buril, altura, ángulo, avance, medición intermedia y acabado forman una secuencia. El torno histórico enseña geometría y tacto, pero la práctica queda condicionada a protección, formación y supervisión modernas.', subsystem:'lathe', sources:['source.private.bulova.03','source.private.chicago.28'], concepts:[['trabajo entre puntos','Sujeción por centros que favorece coaxialidad de superficies torneadas.'],['altura de corte','Posición del filo respecto al eje que altera geometría y estabilidad.'],['pasada de acabado','Retirada final controlada que busca dimensión y superficie sin sobrecorrección.']], sequence:['evaluar riesgo','preparar centros','afilar y apoyar buril','desbastar','medir sin rotación','acabar y verificar'], quantities:['diámetro','conicidad','excentricidad','rugosidad','velocidad segura'], caseStudy:'Una pieza brillante puede estar cónica; una dimensión correcta en un punto puede ocultar falta de coaxialidad. La evidencia incluye varias secciones y referencia de montaje.', failures:['Medir con el torno en marcha.','Compensar buril romo con más fuerza.'], misconception:{expression:'El torno produce concentricidad por sí solo', correction:'centros, sujeción, herramienta, medición y secuencia determinan el resultado.'}, transfer:'Fabrica solo en entorno supervisado una probeta y registra diámetro, conicidad y acabado.' }),
  U({ route:'micromechanics', slug:'bulova-eje-pivotes', title:'Pasaporte V: eje de volante, pivotes y hombros', question:'¿Cómo se conserva coaxialidad al fabricar una geometría escalonada?', core:'Un eje integra centros, pivotes, hombros, asiento de volante, asiento de platillo y zona de virola. El orden de operaciones protege referencias y deja material para acabado. Cada cota se relaciona con una interfaz, no con una copia visual.', subsystem:'balance-staff', sources:['source.private.bulova.03a','source.private.daniels.turning'], concepts:[['hombro funcional','Transición que posiciona axialmente una pieza o limita un apoyo.'],['coaxialidad','Coincidencia de ejes de superficies que deben girar juntas.'],['sobrematerial de acabado','Material reservado para bruñido o ajuste posterior.']], sequence:['levantar plano de interfaces','preparar bruto y centros','tornear diámetros mayores','formar hombros','dejar pivotes','bruñir y probar'], quantities:['diámetro de pivote','altura total','asientos','conicidad','juego axial'], caseStudy:'Copiar la longitud total sin identificar hombros puede producir un eje que cabe pero no sitúa platillo o volante. El plano debe derivarse de interfaces y pieza de referencia trazable.', failures:['Terminar pivote antes de operaciones que pueden dañarlo.','Medir un eje doblado como referencia.'], misconception:{expression:'Un eje sirve si entra en los rubíes', correction:'también debe posicionar volante, platillo y espiral con juegos y alturas correctos.'}, transfer:'Elabora un plano funcional de un eje sin asignar tolerancias no medidas.' }),
  U({ route:'micromechanics', slug:'bulova-tija', title:'Pasaporte VI: fabricación y ajuste de una tija', question:'¿Qué funciones deben conservarse al fabricar una tija además de longitud y rosca?', core:'La tija transmite rotación, desplaza el piñón corredizo, interactúa con tirete y corona y atraviesa caja. Diámetros, cuadrados, hombros, roscas y acabado dependen de cada interfaz. Acortar es irreversible y se planifica tras fijar caja y movimiento.', subsystem:'stem', sources:['source.private.bulova.03b','source.private.chicago.2'], concepts:[['cuadrado de tija','Sección que transmite par permitiendo desplazamiento de piezas asociadas.'],['hombro de posición','Cambio de diámetro que limita recorrido o sitúa un componente.'],['longitud de caja','Dimensión final dependiente de tubo, corona, anillo y posición del movimiento.']], sequence:['identificar funciones','medir referencia','tornear escalones','formar cuadrado','roscar y probar corona','ajustar longitud al conjunto'], quantities:['diámetros','longitud de rosca','sección cuadrada','recorridos de corona'], caseStudy:'Una tija que da cuerda fuera de caja puede no alcanzar posiciones dentro por longitud, tubo o corona. La prueba funcional se hace en conjunto y por posiciones.', failures:['Cortar a longitud antes de montar anillo.','Forzar corona en rosca incompatible.'], misconception:{expression:'Una tija es una varilla roscada', correction:'es un eje funcional escalonado que transmite par y posición a varias interfaces.'}, transfer:'Construye una tabla posición-función-contactos antes de dimensionar.' }),
  U({ route:'micromechanics', slug:'bulova-brunido', title:'Pasaporte VII: bruñido de pivotes', question:'¿Cómo mejora el bruñido una superficie sin destruir forma ni diámetro?', core:'El bruñido desplaza y alisa material mediante herramienta preparada y apoyo controlado. Cilindricidad, hombro, extremo, diámetro y acabado se evalúan juntos. Brillo no equivale a geometría ni ausencia de daño.', subsystem:'pivot-finishing', sources:['source.private.bulova.04','source.private.daniels.turning'], concepts:[['bruñidor','Herramienta de superficie preparada que comprime y alisa el metal.'],['cilindricidad del pivote','Constancia geométrica de la superficie alrededor de su eje.'],['radio de hombro','Transición que afecta apoyo, resistencia y libertad frente al rubí.']], sequence:['inspeccionar daño','medir diámetro','preparar bruñidor','apoyar pieza','bruñir por etapas','medir forma y acabado'], quantities:['diámetro','ovalidad','conicidad','rugosidad','radio'], caseStudy:'Eliminar un surco profundo hasta obtener brillo puede dejar el pivote bajo medida. La decisión correcta puede ser sustituir o repivotar, no seguir retirando material.', failures:['Evaluar solo por reflejo.','Redondear el hombro hasta perder apoyo.'], misconception:{expression:'Bruñir es pulir más fino', correction:'el proceso, la herramienta y el efecto superficial son distintos y deben conservar geometría funcional.'}, transfer:'Compara antes/después con medidas y fotografías bajo la misma iluminación.' }),
  U({ route:'escapements-chronometry', slug:'bulova-centrado-volante', title:'Pasaporte VIII: centrado y alabeo del volante', question:'¿Cómo se distinguen error radial, axial y desplazamiento de montaje?', core:'El volante se observa respecto al eje y a referencias estables. Error en redondo, alabeo plano y asiento desplazado producen movimientos distintos. Las correcciones son pequeñas, localizadas y posteriores al diagnóstico.', subsystem:'balance', sources:['source.private.bulova.02','source.private.chicago.16'], concepts:[['error radial','Variación de distancia de la llanta al eje durante una vuelta.'],['alabeo axial','Desviación de la llanta fuera de un plano perpendicular al eje.'],['referencia de observación','Punto fijo que permite distinguir movimiento real de perspectiva.']], sequence:['verificar montaje','elegir referencia','girar lentamente','clasificar radial o axial','corregir localmente','repetir vuelta completa'], quantities:['desviación radial','desviación axial','zona angular','repetibilidad'], caseStudy:'Una llanta aparentemente ondulada con referencia inclinada puede ser artefacto visual. Se cambia ángulo y se confirma con referencia antes de deformar.', failures:['Corregir ambos errores a la vez.','Usar el puente como referencia si está inclinado.'], misconception:{expression:'Truing significa que el volante se vea centrado', correction:'requiere separar geometría radial, axial y montaje sobre el eje.'}, transfer:'Registra un mapa angular de error y justifica cada corrección.' }),
  U({ route:'escapements-chronometry', slug:'bulova-poising', title:'Pasaporte IX: equilibrado estático del volante', question:'¿Qué demuestra y qué no demuestra una prueba de poising?', core:'Con fricción mínima, un punto pesado tiende a quedar abajo. Limpieza, pivotes, herramienta nivelada y repetición son condiciones previas. El equilibrio estático no prueba comportamiento dinámico ni corrige espiral.', subsystem:'balance', sources:['source.private.bulova.05','source.private.chicago.17'], concepts:[['punto pesado','Región cuyo exceso de momento gravitatorio orienta el volante.'],['cuchillas de equilibrado','Apoyo de baja fricción para observar tendencia estática.'],['corrección de masa','Cambio controlado de distribución que exige autoridad y revisión.']], sequence:['limpiar y verificar pivotes','nivelar herramienta','colocar volante','observar varias liberaciones','localizar tendencia','revisar antes de corregir'], quantities:['número de repeticiones','posición angular','masa retirada o añadida','estado de tornillos'], caseStudy:'Una misma posición final puede deberse a punto pesado o fricción del apoyo. Girar la pieza, repetir y comprobar pivotes separa hipótesis.', failures:['Retirar material tras una sola caída.','Equilibrar con suciedad o piezas sueltas.'], misconception:{expression:'Poising correcto garantiza buena marcha posicional', correction:'solo evalúa una parte estática del sistema; espiral, pivotes y escape siguen influyendo.'}, transfer:'Diseña evidencia mínima para aceptar, repetir o detener la prueba.' }),
  U({ route:'escapements-chronometry', slug:'bulova-espiral', title:'Pasaporte X: plano, centrado, virola y vibrado de espiral', question:'¿Qué orden evita corregir frecuencia sobre una espiral geométricamente defectuosa?', core:'Primero se documenta y corrige plano y centrado, luego fijación de virola y pitón, libertad y batido; el vibrado compara frecuencia con referencia. Cada doblez altera relaciones vecinas y requiere nueva observación.', subsystem:'hairspring', sources:['source.private.bulova.06','source.private.bulova.07','source.private.bulova.08'], concepts:[['vibrado de espiral','Ajuste comparativo de longitud para aproximar la frecuencia del conjunto.'],['colletado','Fijación y orientación de la espiral en su virola.'],['curva terminal','Geometría exterior destinada a mejorar respiración y comportamiento.']], sequence:['fotografiar estado','corregir plano','corregir centrado','fijar virola y pitón','establecer batido','vibrar y verificar'], quantities:['separación vertical','concentricidad','frecuencia','batido','longitud activa'], caseStudy:'Acortar para corregir marcha antes de resolver un roce cambia el síntoma pero conserva la causa. El orden geométrico precede al ajuste de frecuencia.', failures:['Manipular varias espiras a la vez.','Formar sobreespiral sin plantilla ni competencia.'], misconception:{expression:'La raqueta corrige cualquier problema de espiral', correction:'solo modifica longitud activa y no repara plano, centrado, batido ni contacto.'}, transfer:'Crea un checklist de inspección sin ejecutar dobleces fuera de supervisión.', lab:{subsystem:'oscillator', commands:['oscillate','set-hairspring-active-length','introduce-fault','inspect','restore'], views:['slow-motion','uncertainty','textual'], type:'error-simulation'} }),
  U({ route:'service-tribology', slug:'bulova-montaje-barrilete', title:'Pasaporte XI: montaje del movimiento y barrilete', question:'¿Qué puntos de control impiden ocultar un defecto bajo la siguiente pieza?', core:'Montar por subconjuntos permite verificar libertad, apoyos, juegos y función antes de cubrir. El barrilete añade energía almacenada y requiere procedimiento seguro, orientación del muelle y cierre sin deformación.', subsystem:'assembly', sources:['source.private.bulova.09','source.private.bulova.09a'], concepts:[['montaje incremental','Secuencia que comprueba cada función antes de añadir la siguiente capa.'],['estado de energía seguro','Condición verificada en la que una operación no libera energía inesperada.'],['punto de control','Observación o medida obligatoria antes de continuar.']], sequence:['verificar limpieza','montar subconjunto','asentar apoyos sin forzar','comprobar libertad','registrar resultado','continuar o detener'], quantities:['juego axial','libertad de giro','par de tornillo documentado si existe','inventario'], caseStudy:'Usar tornillos para bajar un puente con pivotes fuera de rubíes puede destruirlos sin resistencia evidente. El puente debe asentar por alineación, no actuar como prensa.', failures:['Cerrar antes de comprobar libertad.','Abrir barrilete con carga desconocida.'], misconception:{expression:'Si el puente atornilla, las ruedas están colocadas', correction:'un tornillo puede forzar el conjunto; la entrada de pivotes y libertad se verifican antes.'}, transfer:'Define puntos de control para tren, escape y automático.' }),
  U({ route:'service-tribology', slug:'bulova-enjaltado-escape', title:'Pasaporte XII: enjaltado y examen del escape', question:'¿Qué evidencia separa posición de rubí, juego y geometría de escape?', core:'El enjaltado por fricción controla altura y posición; el escape exige observar bloqueo, caída, impulso y seguridad. Los procedimientos con goma laca y calor quedan bloqueados como práctica hasta revisión moderna y supervisión.', subsystem:'jewelling-escapement', sources:['source.private.bulova.09b','source.private.bulova.10','source.private.bulova.10a'], concepts:[['altura de rubí','Posición axial que participa en juego y alineación del móvil.'],['ajuste por fricción','Retención de una piedra mediante interferencia controlada en su alojamiento.'],['examen funcional del escape','Observación sistemática de fases y seguridad antes de corregir.']], sequence:['identificar estado y riesgo','medir juego','observar fases','localizar primera desviación','planificar corrección','revisar humanamente antes de actuar'], quantities:['juego axial','altura de piedra','bloqueo','caída','holgura de guardia'], caseStudy:'Mover una piedra para corregir juego puede cambiar profundidad de engrane o altura del móvil. La corrección se vincula a todas las interfaces afectadas.', failures:['Calentar goma laca desde una instrucción histórica.','Corregir paletas antes de verificar tren y topes.'], misconception:{expression:'Cada ajuste afecta una sola medida', correction:'la posición de una piedra o paleta modifica varias interfaces y debe revisarse como sistema.'}, transfer:'Redacta un expediente de diagnóstico y déjalo pendiente de revisión física.' }),
]

const CHICAGO_UNITS = [
  U({ route:'cases-water', slug:'chicago-caja-corona-tija', title:'Expediente Chicago I: caja, corona, tubo y tija', question:'¿Cómo se diagnostica un mando exterior sin atribuir todo el fallo a la tija?', core:'Corona, tubo o pendant, rosca, junta, tija, embrague y tirete forman una cadena. Se documentan posiciones, holguras, roscas y condición de caja antes de acortar o sustituir. Las nomenclaturas históricas se traducen sin asumir compatibilidad.', subsystem:'case-controls', sources:['source.private.chicago.1','source.private.chicago.2','source.private.chicago.4'], concepts:[['mando exterior','Conjunto de interfaces que transmite la acción de la persona al mecanismo.'],['manga o sleeve','Componente histórico de ciertos sistemas de pendant que guía o retiene la tija.'],['compatibilidad de rosca','Coincidencia demostrada de diámetro, paso, forma y longitud útil.']], sequence:['identificar arquitectura','registrar posiciones','inspeccionar corona y tubo','medir tija','probar mecanismo sin caja','comparar resultado montado'], quantities:['paso de rosca','longitud','recorrido axial','diámetro de tubo'], caseStudy:'Una corona que no mantiene posición puede implicar sleeve histórico, tirete, tija o interferencia de caja. Probar dentro y fuera separa el mando exterior del mecanismo interno.', failures:['Acortar la tija para compensar una corona incorrecta.','Comprar por diámetro aparente de rosca.'], misconception:{expression:'Si la corona gira, la tija funciona', correction:'también debe transmitir posiciones, recorrido y par sin interferencia.'}, transfer:'Compara un sistema de pendant de bolsillo con una corona moderna roscada.' }),
  U({ route:'cases-water', slug:'chicago-cristales-fijaciones', title:'Expediente Chicago II: cristales, biseles y fijaciones', question:'¿Qué debe verificarse antes de prensar o cementar un cristal?', core:'Tipo de cristal, asiento, bisel, tensión, altura de agujas, material y método de retención determinan el montaje. Los cementos históricos no se trasladan; se conserva la lógica de identificación y medición.', subsystem:'case-crystal', sources:['source.private.chicago.3','source.private.toh.ch12'], concepts:[['asiento de cristal','Geometría que centra, apoya y retiene el cristal.'],['interferencia de montaje','Diferencia dimensional controlada que genera retención al ensamblar.'],['holgura de indicación','Espacio necesario para que las agujas se muevan sin tocar cristal o esfera.']], sequence:['clasificar construcción','limpiar e inspeccionar asiento','medir varias direcciones','comprobar altura interior','elegir método compatible','montar y verificar'], quantities:['diámetro mínimo y máximo','altura','ovalidad','interferencia','holgura'], caseStudy:'Un asiento oval puede retener en un eje y fracturar en otro. Una sola lectura de calibre no describe forma; se miden direcciones y se decide si reparar el asiento.', failures:['Prensar hasta que parezca asentado.','Reutilizar un adhesivo histórico sin ficha de seguridad.'], misconception:{expression:'El cristal correcto es el que tiene el mismo diámetro', correction:'perfil, altura, material, asiento y método de retención también son funcionales.'}, transfer:'Crea una ficha de selección para tres arquitecturas de cristal.' }),
  U({ route:'mechanical-energy-trains', slug:'chicago-muelles-seleccion', title:'Expediente Chicago III: selección de muelle real', question:'¿Cómo se elige un muelle cuando faltan referencias de pieza?', core:'La selección histórica usa barrilete, anchura, espesor, longitud, ganchos y ocupación. Hoy se prioriza la referencia documentada; si no existe, las mediciones se registran como reconstrucción y no como dato oficial.', subsystem:'mainspring', sources:['source.private.chicago.5','source.private.chicago.7','source.private.toh.ch04'], concepts:[['factor de ocupación','Proporción del barrilete ocupada por el muelle enrollado bajo un modelo declarado.'],['gancho de muelle','Interfaz interior o exterior que transmite carga según arquitectura.'],['reconstrucción dimensional','Selección basada en mediciones e hipótesis cuando falta referencia autorizada.']], sequence:['buscar referencia','identificar arquitectura','medir barrilete y muelle','calcular ocupación','verificar ganchos','probar bajo protocolo'], quantities:['altura','espesor','longitud','diámetro interior','vueltas'], caseStudy:'Un muelle antiguo deformado no es una referencia geométrica ideal, pero contiene información de altura y ganchos. Se cruzan catálogo, pieza, barrilete y objetivo sin convertir una fórmula histórica en especificación.', failures:['Enderezar antes de documentar.','Elegir solo por calibre nominal.'], misconception:{expression:'La longitud original puede medirse estirando el muelle usado', correction:'deformación y riesgo hacen necesaria una reconstrucción con varias evidencias.'}, transfer:'Compara selección por referencia y por reconstrucción, con diferentes niveles de confianza.' }),
  U({ route:'mechanical-energy-trains', slug:'chicago-barriletes-especiales', title:'Expediente Chicago IV: barriletes motor, enjoyados y stopwork', question:'¿Qué cambia en la cadena de par al cambiar la arquitectura del barrilete?', core:'Barriletes motor y enjoyados modifican miembros de entrada, salida y apoyos; stopwork limita vueltas para usar una zona del muelle. Los nombres históricos se entienden mediante funciones y relaciones, no como variantes estéticas.', subsystem:'barrel', sources:['source.private.chicago.6','source.private.toh.ch04'], concepts:[['barrilete enjoyado','Conjunto cuyos apoyos incorporan piedras para controlar fricción y desgaste.'],['stopwork','Mecanismo que limita el rango de cuerda y descarga.'],['miembro de salida','Pieza del conjunto desde la que el par se entrega al tren.']], sequence:['identificar entrada','seguir carga del muelle','localizar miembro fijo','localizar salida','detectar limitador','comprobar apoyos'], quantities:['vueltas permitidas','juego del árbol','relación de stopwork','par en rango'], caseStudy:'Desmontar un stopwork sin registrar fase puede impedir recuperar el rango previsto. Antes de separar se fotografía, marca estado de carga y consulta documentación.', failures:['Generalizar el going barrel.','Montar stopwork por simetría visual.'], misconception:{expression:'Todos los barriletes dan salida por el tambor', correction:'la ruta depende de qué miembro gira, cuál se fija y cómo se conecta el tren.'}, transfer:'Dibuja rutas de par para tres arquitecturas.' }),
  U({ route:'service-tribology', slug:'chicago-limpieza-segura', title:'Expediente Chicago V: limpieza histórica y sustitución segura', question:'¿Qué conocimiento puede conservarse de un capítulo con disolventes hoy inaceptables?', core:'Se conserva clasificación de piezas, necesidad de desmontar, control de contaminación, enjuague, secado e inspección. Cianuro, tetracloruro de carbono, bencina y otros productos quedan bloqueados; ninguna receta histórica aparece como instrucción ejecutable.', subsystem:'cleaning', sources:['source.private.chicago.10','source.private.toh.ch13'], concepts:[['cuarentena de procedimiento','Bloqueo editorial que permite estudiar contexto sin ofrecer pasos peligrosos.'],['compatibilidad de limpieza','Adecuación demostrada entre proceso, material, recubrimiento y contaminante.'],['verificación poslimpieza','Inspección de residuos, corrosión y daño antes de montar o lubricar.']], sequence:['identificar material','clasificar contaminante','bloquear sustancias históricas','consultar proceso moderno','separar piezas sensibles','verificar resultado'], quantities:['concentración y temperatura solo desde ficha vigente','tiempo de proceso','residuo observable','trazabilidad de lote'], caseStudy:'Una receta que limpiaba acero puede destruir laca, esfera, adhesivo o componente electrónico. La elección moderna se hace por material y ficha de seguridad, no por costumbre.', failures:['Mostrar cantidades de una receta bloqueada.','Asumir que uso personal reduce toxicidad.'], misconception:{expression:'Un método antiguo probado es seguro', correction:'la experiencia histórica no sustituye toxicología, regulación ni compatibilidad moderna.'}, transfer:'Convierte un procedimiento histórico en un mapa de funciones sin nombres ni cantidades de sustancias peligrosas.' }),
  U({ route:'service-tribology', slug:'chicago-ensamblaje-control', title:'Expediente Chicago VI: montaje, cuerda y puesta en hora', question:'¿Cómo se separan fallos de montaje, cuerda y puesta en hora?', core:'El montaje incremental comprueba tren; la cuerda añade trinquete, rueda de corona y barrilete; la puesta en hora añade tija, tirete, piñón corredizo y minutería. Una matriz por posiciones evita desmontar todo ante un síntoma.', subsystem:'assembly-keyless', sources:['source.private.chicago.8','source.private.chicago.9'], concepts:[['matriz posición-función','Tabla que relaciona cada posición de mando con engranes y resultados esperados.'],['prueba incremental','Comprobación tras cada capa antes de ocultar sus interfaces.'],['retroceso de corona','Respuesta de la cadena de cuerda al liberar el mando, condicionada por clic y trinquete.']], sequence:['montar tren','probar libertad','añadir cuerda','probar retención','añadir puesta en hora','probar cada posición'], quantities:['juego','par cualitativo','recorrido de tija','funciones por posición'], caseStudy:'Si da cuerda pero no pone en hora, el barrilete no es primera hipótesis. La matriz localiza la bifurcación a partir del piñón corredizo y el estado del tirete.', failures:['Cerrar esfera antes de probar keyless.','Forzar una posición que no entra.'], misconception:{expression:'La tija acciona directamente todas las funciones', correction:'selecciona rutas mediante componentes que engranan de forma distinta por posición.'}, transfer:'Construye la matriz para un calibre documentado y compárala con otro.' }),
  U({ route:'math-physics-metrology', slug:'chicago-cronometria-maquinas', title:'Expediente Chicago VII: de Watch Master y Time-O-Graph al cronocomparador', question:'¿Qué principios de señal permanecen aunque cambie el instrumento?', core:'Los instrumentos históricos detectan impulsos acústicos y representan intervalos, marcha y beat. La tecnología cambia, pero siguen importando frecuencia configurada, calidad de captación, ruido, posición y ventana. Las trazas antiguas se estudian como casos de interpretación.', subsystem:'timing-instrument', sources:['source.private.chicago.33','source.private.chicago.34','source.private.chicago.11'], concepts:[['traza de marcha','Representación temporal de la diferencia entre impulsos observados y referencia.'],['beat error','Asimetría temporal entre alternancias asociada a la fase del escape.'],['artefacto de captación','Patrón causado por micrófono, ruido, configuración o contacto, no por el movimiento.']], sequence:['configurar frecuencia','captar sonido','detectar eventos','comparar intervalos','dibujar traza','correlacionar con observación'], quantities:['alternancias por hora','s/d','ms de beat error','amplitud estimada con ángulo declarado','duración'], caseStudy:'Una frecuencia configurada incorrectamente puede crear una marcha aparente absurda. Antes de abrir el reloj se valida configuración, contacto y repetición en varias posiciones.', failures:['Diagnosticar desde una captura breve.','Tratar amplitud calculada como medida directa universal.'], misconception:{expression:'La pantalla del cronocomparador muestra la causa', correction:'muestra una señal interpretada; varias causas y artefactos pueden producir patrones parecidos.'}, transfer:'Interpreta la misma señal con dos hipótesis y diseña una prueba discriminante.' }),
  U({ route:'micromechanics', slug:'chicago-rubies-antichoque', title:'Expediente Chicago VIII: rubíes, contrapiedras y antichoque', question:'¿Cómo se decide altura, juego y orientación sin mezclar sistemas?', core:'Rubíes de agujero, contrapiedras, chatones y resortes antichoque controlan apoyo radial, axial y retención. Factory-set y friction jeweling describen métodos distintos. Se identifica sistema y documenta orientación antes de liberar el resorte.', subsystem:'jewelling', sources:['source.private.chicago.12','source.private.chicago.13','source.private.chicago.14'], concepts:[['contrapiedra','Superficie de apoyo axial que trabaja con el extremo del pivote.'],['chatón','Soporte separado que aloja una piedra y se fija en platina o puente.'],['resorte antichoque','Retenedor elástico que permite desplazamiento controlado y retorno del conjunto.']], sequence:['identificar sistema','contener resorte','documentar caras','medir juego','ajustar solo con autoridad','montar y comprobar libertad'], quantities:['juego axial','altura de rubí','diámetro de ajuste','planitud de contrapiedra'], caseStudy:'Invertir una contrapiedra o mezclar resortes puede permitir montaje y alterar contacto. El inventario por cara y posición es parte del procedimiento.', failures:['Abrir resorte sin contención.','Empujar piedra para resolver un síntoma no medido.'], misconception:{expression:'Todos los rubíes se ajustan igual', correction:'función, montaje, forma y sistema determinan herramientas y criterios.'}, transfer:'Compara un apoyo simple, una contrapiedra y un conjunto antichoque.' }),
  U({ route:'micromechanics', slug:'chicago-escape-dibujo', title:'Expediente Chicago IX: construcción geométrica del escape', question:'¿Para qué sirve dibujar un escape antes de ajustarlo?', core:'La construcción geométrica relaciona centros, líneas de acción, paletas, bloqueos, impulsos y seguridad. El dibujo ideal entrena dependencias; no reemplaza mediciones de una pieza ni autoriza mover paletas.', subsystem:'escapement-geometry', sources:['source.private.chicago.24','source.private.chicago.25','source.private.toh.ch06'], concepts:[['línea de centros','Referencia geométrica entre ejes de rueda de escape, áncora y volante.'],['plano de impulso','Superficie o dirección que gobierna transferencia durante el contacto.'],['construcción nominal','Geometría ideal definida por reglas antes de tolerancias y desgaste.']], sequence:['situar centros','trazar arcos','definir paletas','construir bloqueo','construir impulso','comprobar seguridad'], quantities:['distancias entre centros','ángulos','radio de rueda','profundidad de paleta'], caseStudy:'Un dibujo puede mostrar que dos ajustes están acoplados. Sin embargo, superponerlo a una foto con perspectiva no convierte píxeles en medidas.', failures:['Escalar desde fotografía sin calibración.','Ajustar para que coincida con un esquema genérico.'], misconception:{expression:'El dibujo define la geometría exacta de cualquier escape', correction:'define relaciones de una construcción; la referencia real requiere plano o medición.'}, transfer:'Construye un esquema normalizado y etiqueta entradas que deben medirse.' }),
  U({ route:'micromechanics', slug:'chicago-escape-emparejado', title:'Expediente Chicago X: emparejar y reparar un escape', question:'¿Qué significa que rueda, áncora y volante formen un conjunto compatible?', core:'Compatibilidad exige centros, diámetros, número y perfil de dientes, paletas, niveles y platillo coherentes. La semejanza visual no basta. La reparación parte de identificar qué relación está fuera de condición y qué corrección es reversible.', subsystem:'escapement-repair', sources:['source.private.chicago.21','source.private.chicago.22','source.private.chicago.26'], concepts:[['matching de escape','Comprobación conjunta de geometría e interfaces de los órganos del escape.'],['condición conjugada','Relación en la que dos superficies cumplen su función a lo largo del contacto previsto.'],['corrección reversible','Prueba o ajuste que puede deshacerse sin perder evidencia ni material.']], sequence:['identificar piezas','medir centros y niveles','observar fases','comparar condiciones','probar hipótesis reversible','revisar antes de modificar'], quantities:['dientes','centros','niveles','bloqueo','caída'], caseStudy:'Cambiar una áncora por otra de igual longitud puede alterar paletas y niveles. Antes de modificar se compara referencia, geometría y ciclo completo.', failures:['Emparejar por longitud total.','Calentar paletas desde un manual histórico.'], misconception:{expression:'Si el reloj arranca, el escape está emparejado', correction:'puede funcionar con condiciones marginales que producen inseguridad, pérdida o mala marcha.'}, transfer:'Crea una matriz de compatibilidad sin ejecutar reparaciones bloqueadas.' }),
  U({ route:'micromechanics', slug:'chicago-torno-repivotado', title:'Expediente Chicago XI: torno, repivotado y piezas perdidas', question:'¿Cómo se decide entre pulir, repivotar, fabricar o sustituir?', core:'La decisión parte de función, material restante, referencia, reversibilidad y riesgo. Repivotar exige taladro coaxial y ajuste; fabricar rueda o cilindro exige datos suficientes. La técnica histórica orienta la secuencia, no certifica tolerancias.', subsystem:'restoration-manufacturing', sources:['source.private.chicago.29','source.private.chicago.30','source.private.chicago.31'], concepts:[['repivotado','Sustitución localizada de un pivote mediante inserto coaxial.'],['pieza perdida','Componente sin muestra suficiente cuya reconstrucción exige interfaces y evidencia indirecta.'],['decisión de conservación','Elección entre intervenir, estabilizar o preservar según valor y evidencia.']], sequence:['documentar daño','definir función y material','medir referencias','comparar opciones','planificar verificación','revisar antes de mecanizar'], quantities:['diámetro y profundidad de taladro','ajuste del inserto','coaxialidad','juego final'], caseStudy:'Pulir un pivote profundamente rayado puede dejarlo insuficiente; repivotar conserva rueda pero añade una interfaz. La elección se justifica con medidas y riesgo, no por preferencia técnica.', failures:['Mecanizar antes de fotografiar.','Fabricar desde una sola pieza deformada.'], misconception:{expression:'La reparación más compleja es la mejor', correction:'la mejor decisión minimiza pérdida y cumple función con evidencia.'}, transfer:'Compara opciones para tres niveles de daño y registra criterios de parada.' }),
  U({ route:'workshop-tools-materials', slug:'chicago-herramientas-seleccion', title:'Expediente Chicago XII: elegir herramientas por capacidad', question:'¿Cómo se construye un taller personal sin comprar por listas históricas o por marca?', core:'La herramienta se selecciona por operación, frecuencia, precisión, riesgo, mantenimiento y evidencia. El volumen Chicago distingue necesidades de aficionado y profesional y propone sustitutos; esas propuestas se revisan hoy por seguridad y capacidad.', subsystem:'workshop-planning', sources:['source.private.chicago.tools','source.private.daniels.workshop-equipment'], concepts:[['capacidad de herramienta','Función y rango que una herramienta puede realizar con calidad verificable.'],['herramienta de referencia','Medio de mayor confianza usado para comprobar o calibrar otro.'],['sustituto controlado','Alternativa que cumple la misma función con riesgos y límites documentados.']], sequence:['definir operación','clasificar frecuencia y riesgo','fijar precisión','comparar capacidades','planificar mantenimiento','comprar tras prueba o evidencia'], quantities:['rango','resolución','repetibilidad','coste total','frecuencia de uso'], caseStudy:'Una herramienta barata puede servir para sujetar piezas de práctica y ser inaceptable para medir pivotes. El presupuesto se asigna según sensibilidad de la operación, no por completar una lista.', failures:['Comprar un kit sin evaluar puntas y acabados.','Usar una herramienta de corte como instrumento de medida.'], misconception:{expression:'Una herramienta profesional produce trabajo profesional', correction:'capacidad, preparación, técnica, mantenimiento y verificación determinan el resultado.'}, transfer:'Construye tres niveles de equipamiento vinculados a competencias y no a marcas.' }),
]

const TM_UNITS = [
  U({ route:'service-tribology', slug:'tm-inspeccion-previa', title:'Caso TM I: inspección antes de desmontar', question:'¿Qué debe aprenderse del reloj mientras todavía conserva su estado de entrada?', core:'El manual militar exige observar identificación, caja, mandos, cuerda, puesta en hora, indicación, marcha y daños antes de desmontar. Esa disciplina sigue siendo válida; productos y procedimientos peligrosos del texto quedan bloqueados.', subsystem:'service-baseline', sources:['source.official.tm9-1575.inspection','source.institutional.awci.standards'], concepts:[['estado de entrada','Condición documentada de la unidad antes de alterar energía, posición o montaje.'],['inspección funcional','Prueba de funciones accesibles sin intervención destructiva.'],['registro de discrepancia','Anotación trazable entre resultado esperado, observado y autoridad.']], sequence:['identificar unidad','fotografiar exterior','probar mandos sin forzar','observar marcha','registrar síntomas','definir alcance'], quantities:['hora de referencia','estado de carga','posiciones probadas','daños e inventario'], caseStudy:'Desmontar de inmediato elimina evidencia sobre cuerda, puesta en hora y síntoma. Una pieza suelta hallada después puede no situarse si no existe fotografía inicial.', failures:['Dar cuerda a un mecanismo bloqueado.','Limpiar antes de documentar residuos.'], misconception:{expression:'La inspección empieza al sacar el movimiento', correction:'empieza con la unidad intacta porque varias funciones y relaciones se pierden al abrir.'}, transfer:'Diseña una ficha de recepción aplicable a reloj de pulsera, bolsillo y cronómetro.' }),
  U({ route:'service-tribology', slug:'tm-diagnostico-sintomas', title:'Caso TM II: diagnóstico por síntomas y prueba discriminante', question:'¿Cómo se usa una tabla histórica de averías sin convertirla en sustitución por receta?', core:'El manual agrupa parada, cuerda, puesta en hora, autonomía, ganancia y error de indicación. Cada síntoma abre varias hipótesis. La Academia transforma la lista en un árbol: primero observación menos invasiva, después prueba que separa causas.', subsystem:'diagnosis', sources:['source.official.tm9-1575.diagnosis','source.private.chicago.35'], concepts:[['síntoma','Resultado observable definido sin incorporar una causa supuesta.'],['hipótesis rival','Explicación alternativa compatible con el mismo síntoma inicial.'],['prueba discriminante','Observación cuyos resultados previstos difieren entre hipótesis.']], sequence:['definir síntoma','registrar condiciones','enumerar causas por función','elegir prueba reversible','actualizar confianza','intervenir solo con evidencia'], quantities:['repetibilidad','estado de carga','marcha','amplitud','consumo cuando aplique'], caseStudy:'Poca reserva puede proceder de muelle, automático, fricción o uso. Sustituir el muelle primero puede ocultar el problema y destruye la oportunidad de medir la cadena original.', failures:['Nombrar causa en la descripción del síntoma.','Elegir la prueba que requiere más desmontaje.'], misconception:{expression:'Una tabla de averías dice qué pieza cambiar', correction:'solo organiza posibilidades; el diagnóstico exige condiciones y pruebas que las separen.'}, transfer:'Construye árboles para parada, no da cuerda y cambia de fecha mal.' }),
  U({ route:'atlas-restoration-design', slug:'tm-hamilton-992b', title:'Caso oficial TM III: Hamilton 992B', question:'¿Cómo se estudia un calibre histórico sin generalizar su secuencia?', core:'El TM documenta identificación, disposición y servicio del Hamilton 992B de 16 líneas y 21 rubíes dentro de la revisión militar. Se usa como expediente primario: cada pieza y paso conserva referencia; las similitudes con otros bolsillos son hipótesis.', subsystem:'historical-calibre', sources:['source.official.tm9-1575.hamilton-992b','source.external.pocket-watch-database'], concepts:[['expediente de calibre','Conjunto de identidad, documentación, piezas, secuencia y evidencia de una referencia.'],['secuencia documentada','Orden respaldado por un manual aplicable, distinto de una deducción visual.'],['transferencia limitada','Aplicación de un principio a otra referencia dejando por confirmar piezas y pasos.']], sequence:['confirmar marcas','vincular revisión','leer despiece','mapear dependencias','simular secuencia documental','comparar con unidad solo si existe'], quantities:['tamaño 16','21 rubíes','referencias de pieza','posiciones de ajuste documentadas'], caseStudy:'Que otro Hamilton de bolsillo comparta tamaño no autoriza la misma pieza ni secuencia. La comparación separa plataforma, variante y revisión.', failures:['Usar el manual como genérico de bolsillos.','Presentar el dibujo como geometría medible completa.'], misconception:{expression:'Un manual oficial es universal dentro de la marca', correction:'su autoridad se limita a referencias, variantes y revisión declaradas.'}, transfer:'Compara 992B y otro calibre dejando una columna de datos no transferibles.' }),
  U({ route:'atlas-restoration-design', slug:'tm-elgin-waltham', title:'Caso oficial TM IV: Elgin y Waltham de bolsillo', question:'¿Qué se aprende al comparar varias plataformas de igual uso militar?', core:'El manual presenta movimientos Elgin y Waltham con arquitecturas y procedimientos propios. La comparación se hace por tren, puentes, cuerda, regulador y servicio; no se reduce a marca o diámetro.', subsystem:'comparative-atlas', sources:['source.official.tm9-1575.elgin-waltham-pocket','source.external.pocket-watch-database'], concepts:[['eje de comparación','Dimensión funcional estable usada para comparar arquitecturas.'],['diferencia de plataforma','Cambio estructural que limita compartir pieza o procedimiento.'],['caso de transferencia','Segunda referencia que prueba si el conocimiento era principio o memoria del primer caso.']], sequence:['definir ejes','identificar cada calibre','alinear subsistemas','registrar similitudes','registrar diferencias','probar transferencia'], quantities:['tamaño','rubíes','frecuencia si está documentada','disposición de puentes'], caseStudy:'Dos movimientos pueden compartir escape de áncora y diferir en acceso, puentes y puesta en hora. Se transfiere la función, no el orden de tornillos.', failures:['Convertir comparación en lista de especificaciones.','Inferir compatibilidad por tamaño.'], misconception:{expression:'Misma función implica mismo servicio', correction:'la función puede implementarse con dependencias y acceso diferentes.'}, transfer:'Explica qué parte del diagnóstico permanece y qué debe releerse.' }),
  U({ route:'atlas-restoration-design', slug:'tm-relojes-pulsera', title:'Caso oficial TM V: Hamilton, Elgin y Waltham de pulsera', question:'¿Qué cambia al pasar del bolsillo a movimientos de pulsera históricos?', core:'Miniaturización, caja, mandos, protección y disposición afectan acceso y fragilidad. El TM permite comparar referencias concretas y revisar cómo un mismo principio de servicio cambia de escala.', subsystem:'historical-calibre', sources:['source.official.tm9-1575.wristwatches','source.external.17jewels'], concepts:[['miniaturización funcional','Reducción de escala que cambia sensibilidad, herramientas y tolerancias.'],['acceso de servicio','Orden y espacio disponibles para alcanzar un subconjunto.'],['fragilidad de interfaz','Riesgo de daño amplificado en pivotes, roscas o muelles pequeños.']], sequence:['identificar tamaño y caja','mapear acceso','comparar puentes','evaluar herramientas','adaptar evidencia','mantener secuencia específica'], quantities:['diámetro','espesor','diámetro de tornillos y pivotes solo si documentado','holgura de caja'], caseStudy:'Una técnica cómoda en 16 líneas puede aplicar fuerzas excesivas en pulsera. La competencia se transfiere mediante criterios, no escala directa de gestos.', failures:['Usar la misma herramienta por costumbre.','Suponer tolerancias proporcionales al tamaño.'], misconception:{expression:'Un reloj pequeño es el mismo trabajo con herramientas pequeñas', correction:'cambian acceso, rigidez, riesgo, medición y sensibilidad a contaminación.'}, transfer:'Adapta un protocolo de inspección de bolsillo a pulsera y justifica cada cambio.' }),
  U({ route:'atlas-restoration-design', slug:'tm-bulova-10ak', title:'Caso oficial TM VI: Bulova 10AK y estanqueidad histórica', question:'¿Cómo se estudia una afirmación histórica de waterproof sin convertirla en garantía actual?', core:'El manual documenta un Bulova 10AK y su caja dentro del lenguaje y pruebas de 1945. Hoy se conserva como historia de interfaces. Una unidad envejecida necesita juntas, asientos y prueba moderna; nunca se declara estanqueidad por denominación.', subsystem:'historical-case', sources:['source.official.tm9-1575.bulova-10ak','source.private.toh.ch12'], concepts:[['declaración histórica de estanqueidad','Término y criterio perteneciente a una fecha y norma determinadas.'],['estado de envejecimiento','Cambios de junta, corrosión, deformación y superficie acumulados por la unidad.'],['prueba no destructiva','Ensayo que evalúa el conjunto limitando la entrada de agua y el daño.']], sequence:['identificar caja','leer criterio histórico','inspeccionar asientos','sustituir solo con datos','realizar prueba moderna','declarar resultado y fecha'], quantities:['presión de prueba','deformación','fuga','fecha y condiciones'], caseStudy:'La palabra waterproof grabada no demuestra la condición actual. Incluso un resultado de prueba es temporal y depende del montaje y del método.', failures:['Mojar para comprobar.','Prometer profundidad por nombre histórico.'], misconception:{expression:'Si era waterproof, puede volver a serlo cambiando la junta', correction:'asientos, corrosión, cristal, corona y prueba determinan el conjunto actual.'}, transfer:'Redacta una comunicación responsable de resultado sin promesa absoluta.' }),
  U({ route:'atlas-restoration-design', slug:'tm-cronometros-reloj-m1', title:'Caso oficial TM VII: stopwatches Elgin y Message Center Clock M1', question:'¿Qué enseñan un cronómetro y un reloj militar grande sobre transferencia entre escalas?', core:'El stopwatch añade mando, embrague, freno y cero; el M1 traslada principios a otra escala, energía y montaje. El manual ofrece casos oficiales delimitados para practicar comparación funcional sin fingir modelos exactos.', subsystem:'historical-instruments', sources:['source.official.tm9-1575.stopwatches','source.official.tm9-1575.clock-m1'], concepts:[['contador de intervalo','Mecanismo dedicado a iniciar, detener y restaurar una medición de duración.'],['reloj de mensaje','Instrumento militar que coordina tiempo y operaciones dentro de una instalación.'],['transferencia de escala','Aplicación de principios a dimensiones y cargas distintas con nueva verificación.']], sequence:['identificar función','separar cadena base y adicional','mapear controles','comparar escala y energía','leer secuencia oficial','declarar límites'], quantities:['duración medida','resolución','reserva','dimensiones solo si documentadas'], caseStudy:'El cronómetro comparte conceptos con un cronógrafo de pulsera pero no necesariamente arquitectura. El reloj M1 comparte regulación y tren, aunque herramientas y cargas cambian.', failures:['Llamar cronógrafo a todo stopwatch.','Trasladar tolerancias entre escalas.'], misconception:{expression:'El principio común permite copiar el procedimiento', correction:'permite formular preguntas; piezas, secuencia, herramientas y criterios deben confirmarse.'}, transfer:'Construye un mapa común y dos columnas de diferencias verificables.' }),
]

